import (
	"image"
	"image/color"
	"image/gif"
	"image/jpeg"
	"image/png"
	"math"
	"os"
)

func main() {
	// gradient image 64x48
	w, h := 64, 48
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			r := uint8(x * 255 / (w - 1))
			g := uint8(y * 255 / (h - 1))
			b := uint8(128)
			img.Set(x, y, color.RGBA{r, g, b, 255})
		}
	}
	f, _ := os.Create("grad.png")
	png.Encode(f, img)
	f.Close()
	f, _ = os.Create("grad.jpg")
	jpeg.Encode(f, img, &jpeg.Options{Quality: 90})
	f.Close()

	// circle image 100x100 with alpha
	img2 := image.NewNRGBA(image.Rect(0, 0, 100, 100))
	for y := 0; y < 100; y++ {
		for x := 0; x < 100; x++ {
			d := math.Hypot(float64(x-50), float64(y-50))
			if d < 40 {
				v := uint8(255 - d*255/40)
				img2.Set(x, y, color.NRGBA{v, 255 - v, 100, 255})
			} else {
				img2.Set(x, y, color.NRGBA{0, 0, 0, 0})
			}
		}
	}
	f, _ = os.Create("circle.png")
	png.Encode(f, img2)
	f.Close()

	// grayscale image 
	img3 := image.NewGray(image.Rect(0, 0, 32, 32))
	for y := 0; y < 32; y++ {
		for x := 0; x < 32; x++ {
			img3.SetGray(x, y, color.Gray{uint8((x + y) * 255 / 62)})
		}
	}
	f, _ = os.Create("gray.png")
	png.Encode(f, img3)
	f.Close()

	// tiny image 3x2
	img4 := image.NewRGBA(image.Rect(0, 0, 3, 2))
	img4.Set(0, 0, color.RGBA{255, 0, 0, 255})
	img4.Set(1, 0, color.RGBA{0, 255, 0, 255})
	img4.Set(2, 0, color.RGBA{0, 0, 255, 255})
	img4.Set(0, 1, color.RGBA{0, 0, 0, 255})
	img4.Set(1, 1, color.RGBA{128, 128, 128, 255})
	img4.Set(2, 1, color.RGBA{255, 255, 255, 255})
	f, _ = os.Create("tiny.png")
	png.Encode(f, img4)
	f.Close()

	// big image 800x600
	img5 := image.NewRGBA(image.Rect(0, 0, 800, 600))
	for y := 0; y < 600; y++ {
		for x := 0; x < 800; x++ {
			v := math.Sin(float64(x)/40) * math.Cos(float64(y)/30)
			img5.Set(x, y, color.RGBA{uint8((v + 1) * 127), uint8(x * 255 / 799), uint8(y * 255 / 599), 255})
		}
	}
	f, _ = os.Create("big.png")
	png.Encode(f, img5)
	f.Close()

	// gif with 3 frames
	g := &gif.GIF{}
	for i := 0; i < 3; i++ {
		pal := color.Palette{color.Black, color.White, color.RGBA{255, 0, 0, 255}, color.RGBA{0, 0, 255, 255}}
		fr := image.NewPaletted(image.Rect(0, 0, 40, 20), pal)
		for y := 0; y < 20; y++ {
			for x := 0; x < 40; x++ {
				idx := uint8(((x/5 + y/5 + i) % 4))
				fr.SetColorIndex(x, y, idx)
			}
		}
		g.Image = append(g.Image, fr)
		g.Delay = append(g.Delay, 50)
	}
	f, _ = os.Create("anim.gif")
	gif.EncodeAll(f, g)
	f.Close()
}
EOF
