{"command":"mkdir -p /tmp/harness && cd /tmp/harness && cat > go.mod <<'EOF'
module harness
go 1.21
EOF
cat > main.go <<'EOF'
package main

import (
	"fmt"
	"image"
	"image/color"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"math"
	"os"
	"strconv"
	"strings"
)

func sinc(x float64) float64 {
	x = math.Pi * x
	if x >= 0.000001 || x <= -0.000001 {
		return math.Sin(x) / x
	}
	return 1
}

func lanczos3(in float64) float64 {
	if in > -3 && in < 3 {
		return sinc(in) * sinc(in*0.3333333333333333)
	}
	return 0
}

func clamp8(v int32) uint8 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint8(v)
}

// weights for 1-D resample to dy outputs over input with given scale (in/out)
func weights(dy, taps int, scale float64, kernel func(float64) float64) ([]int16, []int, int) {
	fl := taps * int(math.Max(math.Ceil(scale), 1))
	factor := math.Min(1./scale, 1)
	coeffs := make([]int16, dy*fl)
	start := make([]int, dy)
	for y := 0; y < dy; y++ {
		ix := scale*(float64(y)+0.5) - 0.5
		start[y] = int(ix) - fl/2 + 1
		ix -= float64(start[y])
		for i := 0; i < fl; i++ {
			in := (ix - float64(i)) * factor
			coeffs[y*fl+i] = int16(kernel(in) * 256)
		}
	}
	return coeffs, start, fl
}

// horizontal pass producing transposed output
func passRGBA(in *image.RGBA, outW int, scale float64) *image.RGBA {
	inW := in.Bounds().Dx()
	inH := in.Bounds().Dy()
	out := image.NewRGBA(image.Rect(0, 0, inH, outW)) // transposed
	coeffs, start, fl := weights(outW, 6, scale, lanczos3)
	maxX := inW - 1
	for x := 0; x < inH; x++ { // out x == in row
		row := in.Pix[x*in.Stride:]
		for y := 0; y < outW; y++ {
			var rgba [4]int32
			var sum int32
			st := start[y]
			ci := y * fl
			for i := 0; i < fl; i++ {
				c := coeffs[ci+i]
				if c != 0 {
					xi := st + i
					if xi < 0 {
						xi = 0
					} else if xi >= maxX {
						xi = maxX
					}
					xi *= 4
					rgba[0] += int32(c) * int32(row[xi+0])
					rgba[1] += int32(c) * int32(row[xi+1])
					rgba[2] += int32(c) * int32(row[xi+2])
					rgba[3] += int32(c) * int32(row[xi+3])
					sum += int32(c)
				}
			}
			xo := y*out.Stride + x*4
			out.Pix[xo+0] = clamp8(rgba[0] / sum)
			out.Pix[xo+1] = clamp8(rgba[1] / sum)
			out.Pix[xo+2] = clamp8(rgba[2] / sum)
			out.Pix[xo+3] = clamp8(rgba[3] / sum)
		}
	}
	return out
}

func toRGBA(img image.Image) *image.RGBA {
	b := img.Bounds()
	out := image.NewRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
	for y := 0; y < b.Dy(); y++ {
		for x := 0; x < b.Dx(); x++ {
			out.Set(x, y, img.At(b.Min.X+x, b.Min.Y+y))
		}
	}
	return out
}

func resizeRGBA(img *image.RGBA, w, h int) *image.RGBA {
	scaleX := float64(img.Bounds().Dx()) / float64(w)
	scaleY := float64(img.Bounds().Dy()) / float64(h)
	t := passRGBA(img, w, scaleX)
	return passRGBA(t, h, scaleY)
}

func main() {
	f, _ := os.Open(os.Args[1])
	img, _, err := image.Decode(f)
	if err != nil {
		fmt.Println(err)
		return
	}
	parts := strings.Split(os.Args[2], ",")
	w, _ := strconv.Atoi(parts[0])
	h, _ := strconv.Atoi(parts[1])
	fmt.Printf("%T\n", img)
	rgba := toRGBA(img)
	out := resizeRGBA(rgba, w, h)
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			c := out.At(x, y).(color.RGBA)
			fmt.Printf("(%d,%d,%d) ", c.R, c.G, c.B)
		}
		fmt.Println()
	}
}
EOF
