package main

import (
	"fmt"
	"image"
	"image/color"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"math"
	"os"
	"strconv"
	"strings"
)

func sinc(x float64) float64 {
	x = math.Pi * x
	if x >= 0.000001 || x <= -0.000001 {
		return math.Sin(x) / x
	}
	return 1
}

func lanczos3(in float64) float64 {
	if in > -3 && in < 3 {
		return sinc(in) * sinc(in*0.3333333333333333)
	}
	return 0
}
func lanczos2(in float64) float64 {
	if in > -2 && in < 2 {
		return sinc(in) * sinc(in*0.5)
	}
	return 0
}
func splineKernel(B, C float64) func(float64) float64 {
	factorA := 2.0 - 1.5*B - C
	factorB := -3.0 + 2.0*B + C
	factorC := 1.0 - 1.0/3.0*B
	factorD := -B/6.0 - C
	factorE := B + 5.0*C
	factorF := -2.0*B - 8.0*C
	factorG := 4.0/3.0*B + 4.0*C
	return func(x float64) float64 {
		x = math.Abs(x)
		if x < 1 {
			return factorA*x*x*x + factorB*x*x + factorC
		} else if x < 2 {
			return factorD*x*x*x + factorE*x*x + factorF*x + factorG
		}
		return 0
	}
}
func bilinear(x float64) float64 {
	x = math.Abs(x)
