package main

import (
	"fmt"
	"image"
)

// 1-D float resample of an RGBA image along X, with output clamped+rounded to uint8
func pass1D(in *image.RGBA, dw int, support float64, kernel func(float64) float64, round bool) *image.RGBA {
	b := in.Bounds()
	sw, sh := b.Dx(), b.Dy()
	xd := distrib(dw, sw, support, kernel)
	out := image.NewRGBA(image.Rect(0, 0, dw, sh))
	for y := 0; y < sh; y++ {
		for x, s := range xd {
			var p [4]float64
			for _, c := range s.cs {
				o := y*in.Stride + c.coord*4
				for k := 0; k < 4; k++ {
					p[k] += float64(in.Pix[o+k]) * c.w
				}
			}
			o := y*out.Stride + x*4
			for k := 0; k < 4; k++ {
				v := p[k] * s.inv
				if round {
					v += 0.5
				}
				if v < 0 {
					v = 0
				}
				if v > 255 {
					v = 255
				}
				out.Pix[o+k] = uint8(v)
			}
		}
	}
	return out
}

func transpose(in *image.RGBA) *image.RGBA {
	b := in.Bounds()
	out := image.NewRGBA(image.Rect(0, 0, b.Dy(), b.Dx()))
	for y := 0; y < b.Dy(); y++ {
		for x := 0; x < b.Dx(); x++ {
			si := y*in.Stride + x*4
			di := x*out.Stride + y*4
			copy(out.Pix[di:di+4], in.Pix[si:si+4])
		}
	}
	return out
}

func runVariants(img *image.RGBA, w, h int) {
	for _, k := range []struct {
		name string
		sup  float64
		f    func(float64) float64
	}{{"catmullrom", 2, catmullRom}, {"bilinear", 1, triangle}, {"lanczos3", 3, func(t float64) float64 { return lanczos3(t) }}, {"lanczos2", 2, func(t float64) float64 { return lanczos2(t) }}, {"mitchell", 2, splineKernel(1.0/3, 1.0/3)}} {
		for _, round := range []bool{false, true} {
			// H then V
			t := pass1D(img, w, k.sup, k.f, round)
			t = transpose(t)
			t = pass1D(t, h, k.sup, k.f, round)
			t = transpose(t)
			fmt.Printf("HV-%s-round%v: ", k.name, round)
			for y := 0; y < h; y++ {
				for x := 0; x < w; x++ {
					o := y*t.Stride + x*4
					fmt.Printf("(%d,%d,%d) ", t.Pix[o], t.Pix[o+1], t.Pix[o+2])
				}
				fmt.Print("| ")
			}
			fmt.Println()
			// V then H
			t = transpose(img)
			t = pass1D(t, h, k.sup, k.f, round)
			t = transpose(t)
			t = pass1D(t, w, k.sup, k.f, round)
			fmt.Printf("VH-%s-round%v: ", k.name, round)
			for y := 0; y < h; y++ {
				for x := 0; x < w; x++ {
					o := y*t.Stride + x*4
					fmt.Printf("(%d,%d,%d) ", t.Pix[o], t.Pix[o+1], t.Pix[o+2])
				}
				fmt.Print("| ")
			}
			fmt.Println()
		}
	}
}
