package main

import (
	"fmt"
	"image"
	"image/color"
	"math"
)

type iw struct {
	idx int
	w   float64
}

func lanczosK(x float64) float64 {
	x = math.Abs(x)
	if x < 3 {
		return sincI(x) * sincI(x/3)
	}
	return 0
}
func sincI(x float64) float64 {
	if x == 0 {
		return 1
	}
	return math.Sin(math.Pi*x) / (math.Pi * x)
}

func precompute(dst, srcN int, support float64, kernel func(float64) float64) [][]iw {
	du := float64(srcN) / float64(dst)
	scale := du
	if scale < 1 {
		scale = 1
	}
	ru := math.Ceil(scale * support)
	out := make([][]iw, dst)
	for v := 0; v < dst; v++ {
		fu := (float64(v)+0.5)*du - 0.5
		begin := int(math.Ceil(fu - ru))
		if begin < 0 {
			begin = 0
		}
		end := int(math.Floor(fu + ru))
		if end > srcN-1 {
			end = srcN - 1
		}
		var sum float64
		var ws []iw
		for u := begin; u <= end; u++ {
			w := kernel((float64(u) - fu) / scale)
			if w != 0 {
				sum += w
				ws = append(ws, iw{u, w})
			}
		}
		if sum != 0 {
			for i := range ws {
				ws[i].w /= sum
			}
		}
		out[v] = ws
	}
	return out
}

func clampF(x float64) uint8 {
	v := int64(x + 0.5)
	if v > 255 {
		return 255
	}
	if v > 0 {
		return uint8(v)
	}
	return 0
}

func toNRGBA(img image.Image) *image.NRGBA {
	b := img.Bounds()
	out := image.NewNRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
	for y := 0; y < b.Dy(); y++ {
		for x := 0; x < b.Dx(); x++ {
			out.Set(x, y, img.At(b.Min.X+x, b.Min.Y+y))
		}
	}
	return out
}

func resizeH(src *image.NRGBA, width int, support float64, kernel func(float64) float64) *image.NRGBA {
	sw, sh := src.Bounds().Dx(), src.Bounds().Dy()
	dst := image.NewNRGBA(image.Rect(0, 0, width, sh))
	ws := precompute(width, sw, support, kernel)
	for y := 0; y < sh; y++ {
		line := src.Pix[y*src.Stride : y*src.Stride+sw*4]
		for x := range ws {
			var r, g, b, a float64
			for _, w := range ws[x] {
				s := line[w.idx*4 : w.idx*4+4]
				aw := float64(s[3]) * w.w
				r += float64(s[0]) * aw
				g += float64(s[1]) * aw
				b += float64(s[2]) * aw
				a += aw
			}
			if a != 0 {
				inv := 1 / a
				j := y*dst.Stride + x*4
				dst.Pix[j] = clampF(r * inv)
				dst.Pix[j+1] = clampF(g * inv)
				dst.Pix[j+2] = clampF(b * inv)
				dst.Pix[j+3] = clampF(a)
			}
		}
	}
	return dst
}

func resizeV(src *image.NRGBA, height int, support float64, kernel func(float64) float64) *image.NRGBA {
	sw, sh := src.Bounds().Dx(), src.Bounds().Dy()
	dst := image.NewNRGBA(image.Rect(0, 0, sw, height))
	ws := precompute(height, sh, support, kernel)
	for x := 0; x < sw; x++ {
		for y := range ws {
			var r, g, b, a float64
			for _, w := range ws[y] {
				i := w.idx*src.Stride + x*4
				s := src.Pix[i : i+4]
				aw := float64(s[3]) * w.w
				r += float64(s[0]) * aw
				g += float64(s[1]) * aw
				b += float64(s[2]) * aw
				a += aw
			}
			if a != 0 {
				inv := 1 / a
				j := y*dst.Stride + x*4
				dst.Pix[j] = clampF(r * inv)
				dst.Pix[j+1] = clampF(g * inv)
				dst.Pix[j+2] = clampF(b * inv)
				dst.Pix[j+3] = clampF(a)
			}
		}
	}
	return dst
}

func imagingResize(img image.Image, w, h int) *image.NRGBA {
	src := toNRGBA(img)
	sw, sh := src.Bounds().Dx(), src.Bounds().Dy()
	if sw == w && sh == h {
		return src
	}
	if sw != w && sh != h {
		return resizeV(resizeH(src, w, 3, lanczosK), h, 3, lanczosK)
	}
	if sw != w {
		return resizeH(src, w, 3, lanczosK)
	}
	return resizeV(src, h, 3, lanczosK)
}

func runImaging(img image.Image, w, h int) {
	out := imagingResize(img, w, h)
	fmt.Println("imaging-like (premultiplied view):")
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			c := color.RGBAModel.Convert(out.At(x, y)).(color.RGBA)
			fmt.Printf("(%d,%d,%d) ", c.R, c.G, c.B)
		}
		fmt.Println()
	}
}
