		g.Delay = append(g.Delay, 20+10*i)
	}
	f, _ := os.Create("../anim7.gif")
	gif.EncodeAll(f, g)
	f.Close()

	// gif with subrect frames
	g = &gif.GIF{}
	fr0 := image.NewPaletted(image.Rect(0, 0, 40, 20), pal)
	for y := 0; y < 20; y++ {
		for x := 0; x < 40; x++ {
			fr0.SetColorIndex(x, y, 1)
		}
	}
	g.Image = append(g.Image, fr0)
	g.Delay = append(g.Delay, 30)
	g.Disposal = append(g.Disposal, gif.DisposalNone)
	fr1 := image.NewPaletted(image.Rect(10, 5, 30, 15), pal)
	for y := 5; y < 15; y++ {
		for x := 10; x < 30; x++ {
			fr1.SetColorIndex(x, y, 2)
		}
	}
	g.Image = append(g.Image, fr1)
	g.Delay = append(g.Delay, 30)
	g.Disposal = append(g.Disposal, gif.DisposalNone)
	fr2 := image.NewPaletted(image.Rect(0, 0, 20, 10), pal)
	for y := 0; y < 10; y++ {
		for x := 0; x < 20; x++ {
			fr2.SetColorIndex(x, y, 3)
		}
	}
	g.Image = append(g.Image, fr2)
	g.Delay = append(g.Delay, 30)
	g.Disposal = append(g.Disposal, gif.DisposalBackground)
	g.Config = image.Config{ColorModel: pal, Width: 40, Height: 20}
	f, _ = os.Create("../subrect.gif")
	gif.EncodeAll(f, g)
	f.Close()

	// single frame gif
	g = &gif.GIF{}
	g.Image = append(g.Image, fr0)
	g.Delay = append(g.Delay, 0)
	f, _ = os.Create("../single.gif")
	gif.EncodeAll(f, g)
	f.Close()
}
