package main

import (
	"image"
	"math"
)

// Separable Lanczos (a=3) resampling working on non-premultiplied RGBA data.
// Colour channels are weighted by alpha while filtering so that fully
// transparent pixels don't bleed their (meaningless) colour into neighbours.

type tapWeight struct {
	index  int
	weight float64
}

func sincFn(x float64) float64 {
	if x == 0 {
		return 1
	}
	return math.Sin(math.Pi*x) / (math.Pi * x)
}

func lanczosKernel(x float64) float64 {
	x = math.Abs(x)
	if x < 3.0 {
		return sincFn(x) * sincFn(x/3.0)
	}
	return 0
}

const lanczosSupport = 3.0

// buildWeights computes, for every destination coordinate, the list of source
// coordinates and normalised weights that contribute to it.
func buildWeights(dstSize, srcSize int) [][]tapWeight {
	du := float64(srcSize) / float64(dstSize)
	scale := du
	if scale < 1.0 {
		scale = 1.0
	}
	ru := math.Ceil(scale * lanczosSupport)

	out := make([][]tapWeight, dstSize)
	for v := 0; v < dstSize; v++ {
		fu := (float64(v)+0.5)*du - 0.5

		begin := int(math.Ceil(fu - ru))
		if begin < 0 {
			begin = 0
		}
		end := int(math.Floor(fu + ru))
		if end > srcSize-1 {
			end = srcSize - 1
		}

		var taps []tapWeight
		var sum float64
		for u := begin; u <= end; u++ {
			w := lanczosKernel((float64(u) - fu) / scale)
			if w != 0 {
				sum += w
				taps = append(taps, tapWeight{index: u, weight: w})
			}
		}
		if sum != 0 {
			for i := range taps {
				taps[i].weight /= sum
			}
		}
		out[v] = taps
	}
	return out
}

func clampToByte(x float64) uint8 {
	v := int64(x + 0.5)
	if v > 255 {
		return 255
	}
	if v > 0 {
		return uint8(v)
	}
	return 0
}

// toNRGBA copies any image into a zero-origin NRGBA image.
func toNRGBA(img image.Image) *image.NRGBA {
	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	dst := image.NewNRGBA(image.Rect(0, 0, w, h))
	if src, ok := img.(*image.NRGBA); ok {
		for y := 0; y < h; y++ {
			si := src.PixOffset(b.Min.X, b.Min.Y+y)
			copy(dst.Pix[y*dst.Stride:y*dst.Stride+w*4], src.Pix[si:si+w*4])
		}
		return dst
	}
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			dst.Set(x, y, img.At(b.Min.X+x, b.Min.Y+y))
		}
	}
	return dst
}

func resampleHorizontal(src *image.NRGBA, width int) *image.NRGBA {
	sw, sh := src.Bounds().Dx(), src.Bounds().Dy()
	dst := image.NewNRGBA(image.Rect(0, 0, width, sh))
	weights := buildWeights(width, sw)
	for y := 0; y < sh; y++ {
		line := src.Pix[y*src.Stride : y*src.Stride+sw*4]
		for x, taps := range weights {
			var r, g, b, a float64
			for _, t := range taps {
				p := line[t.index*4 : t.index*4+4]
				aw := float64(p[3]) * t.weight
				r += float64(p[0]) * aw
				g += float64(p[1]) * aw
				b += float64(p[2]) * aw
				a += aw
			}
			if a != 0 {
				inv := 1 / a
				o := y*dst.Stride + x*4
				dst.Pix[o+0] = clampToByte(r * inv)
				dst.Pix[o+1] = clampToByte(g * inv)
				dst.Pix[o+2] = clampToByte(b * inv)
				dst.Pix[o+3] = clampToByte(a)
			}
		}
	}
	return dst
}

func resampleVertical(src *image.NRGBA, height int) *image.NRGBA {
	sw, sh := src.Bounds().Dx(), src.Bounds().Dy()
	dst := image.NewNRGBA(image.Rect(0, 0, sw, height))
	weights := buildWeights(height, sh)
	for x := 0; x < sw; x++ {
		for y, taps := range weights {
			var r, g, b, a float64
			for _, t := range taps {
				i := t.index*src.Stride + x*4
				p := src.Pix[i : i+4]
				aw := float64(p[3]) * t.weight
				r += float64(p[0]) * aw
				g += float64(p[1]) * aw
				b += float64(p[2]) * aw
				a += aw
			}
			if a != 0 {
				inv := 1 / a
				o := y*dst.Stride + x*4
				dst.Pix[o+0] = clampToByte(r * inv)
				dst.Pix[o+1] = clampToByte(g * inv)
				dst.Pix[o+2] = clampToByte(b * inv)
				dst.Pix[o+3] = clampToByte(a)
			}
		}
	}
	return dst
}

// resizeImage scales img to exactly width x height pixels.
func resizeImage(img image.Image, width, height int) *image.NRGBA {
	if width <= 0 || height <= 0 {
		return image.NewNRGBA(image.Rect(0, 0, 0, 0))
	}
	src := toNRGBA(img)
	sw, sh := src.Bounds().Dx(), src.Bounds().Dy()
	if sw <= 0 || sh <= 0 {
		return image.NewNRGBA(image.Rect(0, 0, 0, 0))
	}
	if sw == width && sh == height {
		return src
	}
	if sw != width && sh != height {
		return resampleVertical(resampleHorizontal(src, width), height)
	}
	if sw != width {
		return resampleHorizontal(src, width)
	}
	return resampleVertical(src, height)
}
