package main

import (
	"image"
	"image/color"
	"strconv"
	"strings"
)

const (
	simpleCharset  = " .:-=+*#%@"
	complexCharset = " .'`^\",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$"
)

// charMap maps a brightness index to the string that should be printed.
//
// The lookup table is keyed by *byte offset* of each rune inside the map
// string while the number of brightness levels equals the number of runes.
// For pure ASCII maps the two coincide; for multi-byte maps some levels end
// up without a character (empty string). This mirrors the behaviour of the
// original tool so the output stays byte-for-byte identical.
type charMap struct {
	levels int
	table  map[int]string
}

func newCharMap(s string) charMap {
	cm := charMap{table: make(map[int]string)}
	for off, r := range s {
		cm.table[off] = string(r)
		cm.levels++
	}
	return cm
}

func (cm charMap) lookup(idx int) string {
	return cm.table[idx]
}

// cell is one character position of the final art.
type cell struct {
	text    string
	r, g, b uint8 // colour used for terminal output (already grayscale/negated if requested)
}

// pixelInfo extracts the displayable colour (alpha composited over black)
// and the luminance of a non-premultiplied pixel.
func pixelInfo(p []uint8) (r, g, b uint8, gray uint8) {
	a := int(p[3])
	r = uint8(int(p[0]) * a / 255)
	g = uint8(int(p[1]) * a / 255)
	b = uint8(int(p[2]) * a / 255)
	gray = color.GrayModel.Convert(color.NRGBA{p[0], p[1], p[2], p[3]}).(color.Gray).Y
	return
}

func flipNRGBA(img *image.NRGBA, flipX, flipY bool) *image.NRGBA {
	if !flipX && !flipY {
		return img
	}
	w, h := img.Bounds().Dx(), img.Bounds().Dy()
	out := image.NewNRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		sy := y
		if flipY {
			sy = h - 1 - y
		}
		for x := 0; x < w; x++ {
			sx := x
			if flipX {
				sx = w - 1 - x
			}
			si := sy*img.Stride + sx*4
			di := y*out.Stride + x*4
			copy(out.Pix[di:di+4], img.Pix[si:si+4])
		}
	}
	return out
}

// renderOptions bundles everything needed to turn pixels into cells.
type renderOptions struct {
	negative  bool
	colored   bool
	grayscale bool
	fontColor [3]int
	hasFont   bool
}

func (o renderOptions) cellColor(r, g, b, gray uint8) (uint8, uint8, uint8) {
	switch {
	case o.colored:
		if o.negative {
			return 255 - r, 255 - g, 255 - b
		}
		return r, g, b
	case o.grayscale:
		if o.negative {
			gray = 255 - gray
		}
		return gray, gray, gray
	case o.hasFont:
		return uint8(o.fontColor[0]), uint8(o.fontColor[1]), uint8(o.fontColor[2])
	}
	return 0, 0, 0
}

// asciiCells converts a (already resized and flipped) image into a grid of cells.
func asciiCells(img *image.NRGBA, cm charMap, o renderOptions) [][]cell {
	w, h := img.Bounds().Dx(), img.Bounds().Dy()
	rows := make([][]cell, h)
	for y := 0; y < h; y++ {
		row := make([]cell, w)
		for x := 0; x < w; x++ {
			p := img.Pix[y*img.Stride+x*4 : y*img.Stride+x*4+4]
			r, g, b, gray := pixelInfo(p)
			idx := int(float64(gray) / 255 * float64(cm.levels))
			if idx >= cm.levels {
				idx = cm.levels - 1
			}
			if o.negative {
