package main

import (
	"image"
	"math"
)

// Floyd-Steinberg error diffusion to a black/white palette, performed in
// linear RGB space (as perceptual dithering libraries do). The result is a
// grayscale image containing only 0 and 255.

var linearTable [256]uint16

func init() {
	for i := 0; i < 256; i++ {
		linearTable[i] = linearize16(uint16(i) * 0x101)
	}
}

func linearize16(v uint16) uint16 {
	f := float32(v) / 65535.0
	var lin float32
	if f <= 0.04045 {
		lin = f / 12.92
	} else {
		lin = float32(math.Pow(float64((f+0.055)/1.055), 2.4))
	}
	return uint16(lin*65535.0 + 0.5)
}

func sqDiff16(a, b uint16) uint32 {
	d := int32(a) - int32(b)
	return uint32(d * d)
}

// ditherToMono returns a Gray image (0/255) of the same size as img.
func ditherToMono(img *image.NRGBA) *image.Gray {
	w, h := img.Bounds().Dx(), img.Bounds().Dy()
	out := image.NewGray(image.Rect(0, 0, w, h))

	// palette in linear space: black and white
	palette := [2][3]uint16{{0, 0, 0}, {65535, 65535, 65535}}

	errs := make([][3]float32, w*h)
	add := func(x, y int, e [3]float32, f float32) {
		if x < 0 || x >= w || y < 0 || y >= h {
			return
		}
		i := y*w + x
		errs[i][0] += e[0] * f
		errs[i][1] += e[1] * f
		errs[i][2] += e[2] * f
	}

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			p := img.Pix[y*img.Stride+x*4 : y*img.Stride+x*4+4]
			// premultiplied 16-bit values like color.Color.RGBA()
			a := uint32(p[3]) * 0x101
			var lin [3]float32
			for c := 0; c < 3; c++ {
				v := uint32(p[c]) * 0x101
				v = v * a / 0xffff
				lin[c] = float32(linearize16(uint16(v))) + errs[y*w+x][c]
				if lin[c] < 0 {
					lin[c] = 0
				} else if lin[c] > 65535 {
					lin[c] = 65535
				}
			}
			q := [3]uint16{uint16(lin[0]), uint16(lin[1]), uint16(lin[2])}
			best, bestIdx := uint32(math.MaxUint32), 0
			for i, pc := range palette {
				d := sqDiff16(q[0], pc[0]) + sqDiff16(q[1], pc[1]) + sqDiff16(q[2], pc[2])
				if d < best {
					best, bestIdx = d, i
				}
			}
			if bestIdx == 1 {
				out.Pix[y*out.Stride+x] = 255
			}
			var e [3]float32
			for c := 0; c < 3; c++ {
				e[c] = lin[c] - float32(palette[bestIdx][c])
			}
			add(x+1, y, e, 7.0/16)
			add(x-1, y+1, e, 3.0/16)
			add(x, y+1, e, 5.0/16)
			add(x+1, y+1, e, 1.0/16)
		}
	}
	return out
}
