			printTypeAError(fmt.Errorf("unable to read piped input: %v", err))
			return nil, false
		}
		return b, true
	case isURL(path):
		fmt.Printf("Fetching file from url...\r")
		resp, err := http.Get(path)
		if err != nil {
			printTypeAError(fmt.Errorf("can't fetch content: %v", err))
			return nil, false
