func (c *converter) convert(path string) (string, error) {
	data, ok := readInput(path)
	if !ok {
		return "", nil
	}

	isGif := strings.HasSuffix(path, ".gif")
	if path == "-" {
		_, format, err := image.DecodeConfig(bytes.NewReader(data))
		if err == nil && format == "gif" {
			isGif = true
		}
	}

	if isGif {
		return c.convertGif(path, data)
	}

	img, _, err := image.Decode(bytes.NewReader(data))
	if err != nil {
		name := path
		if path == "-" {
			name = "piped input"
		}
		printTypeAError(fmt.Errorf("can't decode %v: %v", name, err))
		return "", nil
	}

	if !c.loadFont() {
		return "", nil
	}

	if !c.checkColorSupport() {
		return "", nil
	}

	w, h := c.dimensions(img.Bounds().Dx(), img.Bounds().Dy())
	rows := c.cellsFor(img, w, h)
	text := renderText(rows, c.oo)

	if c.flags.SaveImagePath != "" {
		if err := c.saveImage(rows, baseName(path)); err != nil {
			return "", err
		}
	}
	if c.flags.SaveTxtPath != "" {
		if err := c.saveTxt(rows, baseName(path)); err != nil {
			return "", err
		}
	}
	return text, nil
}

// loadFont loads a custom font if requested. Reports false on failure.
func (c *converter) loadFont() bool {
	if c.flags.FontFilePath == "" {
		return true
	}
	data, err := os.ReadFile(c.flags.FontFilePath)
	if err != nil {
		printTypeAError(fmt.Errorf("unable to open font file: %v", err))
		return false
	}
	f, err := parseTTF(data)
	if err != nil {
		printTypeAError(fmt.Errorf("unable to parse font file: %v", err))
		return false
	}
	c.font = f
	return true
}

// checkColorSupport resolves the terminal colour depth when colours are requested.
func (c *converter) checkColorSupport() bool {
	if !c.oo.useColor {
		return true
	}
	if noColorRequested() {
		c.oo.mode = colorNone
		return true
	}
	mode := detectColorMode()
	if mode == colorNone {
		printTypeAError(errors.New("your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available"))
		return false
	}
	c.oo.mode = mode
	return true
}

// dimensions computes the ascii art size in characters.
func (c *converter) dimensions(imgW, imgH int) (int, int) {
	f := c.flags
	var w, h int
	switch {
	case f.Full:
		termW, _ := terminalSize()
		w = termW - 1
		h = int(float64(w)*float64(imgH)/float64(imgW)) / 2
	case len(f.Dimensions) == 2:
		w, h = f.Dimensions[0], f.Dimensions[1]
	case f.Width != 0:
		w = f.Width
		h = int(float64(w)*float64(imgH)/float64(imgW)) / 2
	case f.Height != 0:
		h = f.Height
		w = int(float64(h)*float64(imgW)/float64(imgH)) * 2
	default:
		termW, termH := terminalSize()
		h = termH - 1
		w = int(float64(h)*float64(imgW)/float64(imgH)) * 2
		if w >= termW {
			w = termW - 1
			h = int(float64(w)*float64(imgH)/float64(imgW)) / 2
		}
	}
	if w < 1 && h >= 1 {
		w = 1
	}
	if h < 1 && w >= 1 {
		h = 1
	}
	return w, h
}

// cellsFor resizes, flips and converts an image to cells.
func (c *converter) cellsFor(img image.Image, w, h int) [][]cell {
	if c.flags.Braille {
		small := resizeImage(img, w*2, h*4)
		small = flipNRGBA(small, c.flags.FlipX, c.flags.FlipY)
		if c.flags.Dither {
			mono := ditherToMono(small)
			return brailleCellsDithered(small, mono, c.ro)
		}
		return brailleCells(small, c.threshold, c.ro)
	}
	small := resizeImage(img, w, h)
	small = flipNRGBA(small, c.flags.FlipX, c.flags.FlipY)
	return asciiCells(small, c.cm, c.ro)
}

// ---- GIF handling ----

func (c *converter) convertGif(path string, data []byte) (string, error) {
	g, err := gif.DecodeAll(bytes.NewReader(data))
	if err != nil {
		name := path
		if path == "-" {
			name = "piped input"
		}
		printTypeAError(fmt.Errorf("can't decode %v: %v", name, err))
		return "", nil
	}

	if !c.loadFont() {
		return "", nil
	}
	if !c.checkColorSupport() {
		return "", nil
	}

	n := len(g.Image)
	if n == 0 {
		return "", nil
	}
	firstW, firstH := g.Image[0].Bounds().Dx(), g.Image[0].Bounds().Dy()
	w, h := c.dimensions(firstW, firstH)

	frames := make([][][]cell, 0, n)
	texts := make([]string, 0, n)
	for i, frame := range g.Image {
		fmt.Printf("Generating ascii art... %v%%\r", i*100/n)
		if frame.Bounds().Dx() != firstW || frame.Bounds().Dy() != firstH {
			return "", fmt.Errorf("%v contains subimages smaller than default width and height\n\nProcess aborted because ascii-image-converter doesn't support subimage placement and transparency in GIFs", path)
		}
		rows := c.cellsFor(frame, w, h)
		frames = append(frames, rows)
		texts = append(texts, renderText(rows, c.oo))
	}
	fmt.Printf("Generating ascii art... 100%%\r")
	fmt.Printf("%s\r", strings.Repeat(" ", 30))

	if c.flags.SaveGifPath != "" {
		name := "piped-gif"
		if path != "-" {
			name = baseName(path)
		}
		if err := c.saveGif(frames, g, name, firstW, firstH); err != nil {
			return "", err
		}
	}

	if c.flags.OnlySave {
		return "", nil
	}

	for {
		for i, t := range texts {
			clearScreen()
			fmt.Println(t)
			delay := 0
			if i < len(g.Delay) {
				delay = g.Delay[i]
			}
			time.Sleep(time.Duration(delay) * 10 * time.Millisecond)
		}
	}
}

func clearScreen() {
	cmd := exec.Command("clear")
	cmd.Stdout = os.Stdout
	_ = cmd.Run()
}
