	"os"
)

func normalizeSavePath(p string) string {
	if len(p) > 0 && p[len(p)-1] != '/' {
		return p + "/"
	}
	return p
}

// saveTxt writes the plain (uncoloured) art to <dir>/<name>-ascii-art.txt.
func (c *converter) saveTxt(rows [][]cell, name string) error {
	dir := normalizeSavePath(c.flags.SaveTxtPath)
	if _, err := os.Stat(dir); err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("can't save file: save path %v does not exist", dir)
		}
		return fmt.Errorf("can't save file: %v", err)
	}
	full := dir + name + "-ascii-art.txt"
	if err := os.WriteFile(full, []byte(plainText(rows)), 0666); err != nil {
		return fmt.Errorf("can't save file: %v", err)
