	if c.flags.OnlySave {
		fmt.Printf("Saved %v\n", full)
	}
	return nil
}

// saveImage renders the art into a PNG file <dir>/<name>-ascii-art.png.
func (c *converter) saveImage(rows [][]cell, name string) error {
	dir := normalizeSavePath(c.flags.SaveImagePath)
	if _, err := os.Stat(dir); err != nil {
		return fmt.Errorf("can't save file: %v", err)
	}
	full := dir + name + "-ascii-art.png"
	if c.flags.OnlySave {
		fmt.Printf("Saved %v\n", full)
	}
	f, err := os.Create(full)
