		return fmt.Errorf("can't save file: %v", err)
	}
	defer f.Close()

	img := c.renderImage(rows, pngCellWidth, pngCellHeight)
	if err := png.Encode(f, img); err != nil {
		return fmt.Errorf("can't save file: %v", err)
	}
	return nil
}

const (
	pngCellWidth  = 14
	pngCellHeight = 28
	imageMargin   = 5
)

// backgroundColor returns the configured background, with opacity scaled
// from percent to the 0-255 range.
func (c *converter) backgroundColor() color.NRGBA {
	a := uint8(255 * c.saveBg[3] / 100)
	return color.NRGBA{uint8(c.saveBg[0]), uint8(c.saveBg[1]), uint8(c.saveBg[2]), a}
}

// renderImage draws the cells with the active font onto a canvas.
func (c *converter) renderImage(rows [][]cell, cellW, cellH float64) *image.NRGBA {
	h := len(rows)
	w := 0
	if h > 0 {
		w = len(rows[0])
	}
	width := int(float64(w)*cellW) + 2*imageMargin
	height := int(float64(h)*cellH) + 2*imageMargin
	img := image.NewNRGBA(image.Rect(0, 0, width, height))
	bg := c.backgroundColor()
	for i := 0; i < len(img.Pix); i += 4 {
		img.Pix[i] = bg.R
		img.Pix[i+1] = bg.G
		img.Pix[i+2] = bg.B
		img.Pix[i+3] = bg.A
	}

	font := c.font
	if font == nil {
		font = defaultFont(c.flags.Braille)
	}
	useColor := c.flags.Colored || c.flags.Grayscale
	for y, row := range rows {
		for x, cl := range row {
			var col color.NRGBA
			if useColor {
				col = color.NRGBA{cl.r, cl.g, cl.b, 255}
			} else {
				col = color.NRGBA{uint8(c.fontColor[0]), uint8(c.fontColor[1]), uint8(c.fontColor[2]), 255}
			}
			ox := float64(imageMargin) + float64(x)*cellW
			oy := float64(imageMargin) + float64(y)*cellH
			font.drawString(img, cl.text, ox, oy, cellW, cellH, col)
		}
	}
	return img
}

// saveGif renders every frame and writes an animated gif.
func (c *converter) saveGif(frames [][][]cell, src *gif.GIF, name string, gifW, gifH int) error {
	n := len(frames)
	out := &gif.GIF{LoopCount: 0}

	// The text area is scaled relative to the source gif: wide art is fitted
	// to the gif height, otherwise to the gif width.
	var cellW, cellH float64
	h := len(frames[0])
	w := 0
	if h > 0 {
		w = len(frames[0][0])
	}
	if w > 2*h {
		cellH = float64(gifH) / float64(h)
		cellW = cellH / 2
	} else {
		cellW = float64(gifW) / float64(w)
		cellH = cellW * 2
	}

	for i, rows := range frames {
		fmt.Printf("Saving gif... %v%%\r", i*100/n)
		img := c.renderImage(rows, cellW, cellH)
		pal := image.NewPaletted(img.Bounds(), nil)
		pal.Palette = buildPalette(img)
		for y := 0; y < img.Bounds().Dy(); y++ {
			for x := 0; x < img.Bounds().Dx(); x++ {
				pal.Set(x, y, img.At(x, y))
			}
		}
		out.Image = append(out.Image, pal)
		delay := 0
		if i < len(src.Delay) {
			delay = src.Delay[i]
		}
		out.Delay = append(out.Delay, delay)
		out.Disposal = append(out.Disposal, gif.DisposalNone)
	}
	fmt.Printf("Saving gif... 100%%\r")

	dir := normalizeSavePath(c.flags.SaveGifPath)
	if _, err := os.Stat(dir); err != nil {
		fmt.Printf("%30s\r", "")
		return fmt.Errorf("can't save file: %v", err)
	}
	full := dir + name + "-ascii-art.gif"
	f, err := os.Create(full)
	if err != nil {
		return fmt.Errorf("can't save file: %v", err)
	}
	defer f.Close()
	if err := gif.EncodeAll(f, out); err != nil {
		return fmt.Errorf("can't save file: %v", err)
	}
	fmt.Printf("%30s\r", "")
	fmt.Printf("Saved %v\n", full)
	return nil
}

// buildPalette collects up to 256 distinct colours of the image (falling
// back to a coarse quantisation when there are more).
func buildPalette(img *image.NRGBA) color.Palette {
	seen := map[color.NRGBA]bool{}
	var pal color.Palette
	for i := 0; i < len(img.Pix); i += 4 {
		c := color.NRGBA{img.Pix[i], img.Pix[i+1], img.Pix[i+2], img.Pix[i+3]}
		if !seen[c] {
			seen[c] = true
			pal = append(pal, c)
			if len(pal) >= 256 {
				break
			}
		}
	}
	if len(pal) == 0 {
		pal = append(pal, color.NRGBA{0, 0, 0, 255})
	}
	return pal
}
