package main

import (
	"encoding/binary"
	"errors"
	"image"
	"image/color"
	"math"
)

// A small TrueType reader/rasteriser sufficient for drawing text onto the
// saved PNG/GIF images.

type ttfFont struct {
	data       []byte
	unitsPerEm float64
	ascender   float64
	descender  float64
	loca       []uint32
	glyf       []byte
	hmtx       []byte
	numHMetric int
	cmap       map[rune]int
	numGlyphs  int
}

type ttfError string

func (e ttfError) Error() string { return "freetype: invalid TrueType format: " + string(e) }

func parseTTF(data []byte) (*ttfFont, error) {
	if len(data) < 12 {
		return nil, ttfError("TTF data is too short")
	}
	offset := 0
	switch binary.BigEndian.Uint32(data) {
	case 0x00010000:
	case 0x74746366: // 'ttcf'
		if len(data) < 16 {
			return nil, ttfError("TTF data is too short")
		}
		offset = int(binary.BigEndian.Uint32(data[12:]))
		if offset+12 > len(data) {
			return nil, ttfError("bad TTC offset")
		}
		if binary.BigEndian.Uint32(data[offset:]) != 0x00010000 {
			return nil, ttfError("bad TTF version")
		}
	default:
		return nil, ttfError("bad TTF version")
	}
	numTables := int(binary.BigEndian.Uint16(data[offset+4:]))
	if offset+12+numTables*16 > len(data) {
		return nil, ttfError("TTF data is too short")
	}
	tables := map[string][]byte{}
	for i := 0; i < numTables; i++ {
		rec := data[offset+12+i*16:]
		tag := string(rec[:4])
		off := int(binary.BigEndian.Uint32(rec[8:]))
		length := int(binary.BigEndian.Uint32(rec[12:]))
		if off < 0 || length < 0 || off+length > len(data) {
			return nil, ttfError("bad table offset")
		}
		tables[tag] = data[off : off+length]
	}
	f := &ttfFont{data: data}
	head, ok := tables["head"]
	if !ok || len(head) < 54 {
		return nil, ttfError("missing head table")
	}
	f.unitsPerEm = float64(binary.BigEndian.Uint16(head[18:]))
	if f.unitsPerEm == 0 {
		return nil, ttfError("bad unitsPerEm")
	}
	indexToLocFormat := binary.BigEndian.Uint16(head[50:])
	maxp, ok := tables["maxp"]
	if !ok || len(maxp) < 6 {
		return nil, ttfError("missing maxp table")
	}
	f.numGlyphs = int(binary.BigEndian.Uint16(maxp[4:]))
	hhea, ok := tables["hhea"]
	if !ok || len(hhea) < 36 {
		return nil, ttfError("missing hhea table")
	}
	f.ascender = float64(int16(binary.BigEndian.Uint16(hhea[4:])))
	f.descender = float64(int16(binary.BigEndian.Uint16(hhea[6:])))
	f.numHMetric = int(binary.BigEndian.Uint16(hhea[34:]))
	f.hmtx = tables["hmtx"]
	loca, ok := tables["loca"]
	if !ok {
		return nil, ttfError("missing loca table")
	}
	f.glyf = tables["glyf"]
	n := f.numGlyphs + 1
	f.loca = make([]uint32, n)
	for i := 0; i < n; i++ {
		if indexToLocFormat == 0 {
			if i*2+2 > len(loca) {
				return nil, ttfError("bad loca table")
			}
			f.loca[i] = uint32(binary.BigEndian.Uint16(loca[i*2:])) * 2
		} else {
			if i*4+4 > len(loca) {
				return nil, ttfError("bad loca table")
			}
			f.loca[i] = binary.BigEndian.Uint32(loca[i*4:])
		}
	}
	cmap, ok := tables["cmap"]
	if !ok {
		return nil, ttfError("missing cmap table")
	}
	if err := f.parseCmap(cmap); err != nil {
		return nil, err
	}
	return f, nil
}

func (f *ttfFont) parseCmap(cmap []byte) error {
	if len(cmap) < 4 {
		return ttfError("bad cmap table")
	}
	n := int(binary.BigEndian.Uint16(cmap[2:]))
	f.cmap = map[rune]int{}
	bestScore := -1
	var best []byte
	for i := 0; i < n; i++ {
		if 4+i*8+8 > len(cmap) {
			break
		}
		pid := binary.BigEndian.Uint16(cmap[4+i*8:])
		eid := binary.BigEndian.Uint16(cmap[6+i*8:])
		off := int(binary.BigEndian.Uint32(cmap[8+i*8:]))
		if off+4 > len(cmap) {
			continue
		}
		score := 0
		switch {
		case pid == 3 && eid == 10:
			score = 4
		case pid == 3 && eid == 1:
			score = 3
		case pid == 0:
			score = 2
		default:
			score = 1
		}
		if score > bestScore {
			bestScore = score
			best = cmap[off:]
		}
	}
	if best == nil {
		return ttfError("no usable cmap subtable")
	}
	format := binary.BigEndian.Uint16(best)
	switch format {
	case 0:
		if len(best) < 6+256 {
			return ttfError("bad cmap subtable")
		}
		for c := 0; c < 256; c++ {
			f.cmap[rune(c)] = int(best[6+c])
		}
	case 4:
		if len(best) < 14 {
			return ttfError("bad cmap subtable")
		}
		segX2 := int(binary.BigEndian.Uint16(best[6:]))
		seg := segX2 / 2
		ends := best[14:]
		starts := best[16+segX2:]
		deltas := best[16+2*segX2:]
		rangeOffs := best[16+3*segX2:]
		if 16+4*segX2 > len(best) {
			return ttfError("bad cmap subtable")
		}
		for s := 0; s < seg; s++ {
			end := int(binary.BigEndian.Uint16(ends[s*2:]))
			start := int(binary.BigEndian.Uint16(starts[s*2:]))
			delta := int(int16(binary.BigEndian.Uint16(deltas[s*2:])))
			ro := int(binary.BigEndian.Uint16(rangeOffs[s*2:]))
			if start > end || end == 0xffff && start == 0xffff {
				continue
			}
			for c := start; c <= end && c != 0xffff; c++ {
				var g int
				if ro == 0 {
					g = (c + delta) & 0xffff
				} else {
					idx := s*2 + ro + (c-start)*2
					if 16+3*segX2+idx+2 > len(best) {
						continue
					}
					g = int(binary.BigEndian.Uint16(rangeOffs[idx:]))
					if g != 0 {
						g = (g + delta) & 0xffff
					}
				}
				if g != 0 {
					f.cmap[rune(c)] = g
				}
			}
		}
	case 6:
		if len(best) < 10 {
			return ttfError("bad cmap subtable")
		}
		first := int(binary.BigEndian.Uint16(best[6:]))
		count := int(binary.BigEndian.Uint16(best[8:]))
		for i := 0; i < count && 10+i*2+2 <= len(best); i++ {
			f.cmap[rune(first+i)] = int(binary.BigEndian.Uint16(best[10+i*2:]))
		}
	case 12:
		if len(best) < 16 {
			return ttfError("bad cmap subtable")
		}
		ngroups := int(binary.BigEndian.Uint32(best[12:]))
		for i := 0; i < ngroups && 16+i*12+12 <= len(best); i++ {
			sc := binary.BigEndian.Uint32(best[16+i*12:])
			ec := binary.BigEndian.Uint32(best[20+i*12:])
			sg := binary.BigEndian.Uint32(best[24+i*12:])
			if ec-sc > 0x10000 {
				ec = sc + 0x10000
			}
			for c := sc; c <= ec; c++ {
				f.cmap[rune(c)] = int(sg + (c - sc))
			}
		}
	default:
		return ttfError("unsupported cmap format")
	}
	return nil
}

func (f *ttfFont) glyphIndex(r rune) int {
	return f.cmap[r]
}

func (f *ttfFont) advance(g int) float64 {
	if f.numHMetric == 0 || len(f.hmtx) < 4 {
		return f.unitsPerEm / 2
	}
	if g >= f.numHMetric {
		g = f.numHMetric - 1
	}
	if g*4+2 > len(f.hmtx) {
		return f.unitsPerEm / 2
	}
	return float64(binary.BigEndian.Uint16(f.hmtx[g*4:]))
}

// point of a flattened outline in font units
type fpoint struct {
	x, y    float64
	onCurve bool
}

// glyphContours returns the contours of a glyph in font units.
func (f *ttfFont) glyphContours(g int, depth int) [][]fpoint {
	if g < 0 || g+1 >= len(f.loca) || depth > 8 {
		return nil
	}
	start, end := f.loca[g], f.loca[g+1]
	if start >= end || int(end) > len(f.glyf) {
		return nil
	}
	d := f.glyf[start:end]
	if len(d) < 10 {
		return nil
	}
	nContours := int(int16(binary.BigEndian.Uint16(d)))
	if nContours < 0 {
		return f.compositeContours(d[10:], depth)
	}
	p := 10
	if p+nContours*2+2 > len(d) {
		return nil
	}
	endPts := make([]int, nContours)
	for i := 0; i < nContours; i++ {
		endPts[i] = int(binary.BigEndian.Uint16(d[p:]))
		p += 2
	}
	nPts := 0
	if nContours > 0 {
		nPts = endPts[nContours-1] + 1
	}
	insLen := int(binary.BigEndian.Uint16(d[p:]))
	p += 2 + insLen
	flags := make([]byte, nPts)
	for i := 0; i < nPts; {
		if p >= len(d) {
			return nil
		}
		fl := d[p]
		p++
		flags[i] = fl
		i++
		if fl&8 != 0 {
			if p >= len(d) {
				return nil
			}
			rep := int(d[p])
			p++
			for j := 0; j < rep && i < nPts; j++ {
				flags[i] = fl
				i++
			}
		}
	}
	xs := make([]float64, nPts)
	ys := make([]float64, nPts)
	var v float64
	for i := 0; i < nPts; i++ {
		fl := flags[i]
		if fl&2 != 0 {
			if p >= len(d) {
				return nil
			}
			dx := float64(d[p])
			p++
			if fl&16 == 0 {
				dx = -dx
			}
			v += dx
		} else if fl&16 == 0 {
			if p+2 > len(d) {
				return nil
			}
			v += float64(int16(binary.BigEndian.Uint16(d[p:])))
			p += 2
		}
		xs[i] = v
	}
	v = 0
	for i := 0; i < nPts; i++ {
		fl := flags[i]
		if fl&4 != 0 {
			if p >= len(d) {
				return nil
			}
			dy := float64(d[p])
			p++
			if fl&32 == 0 {
				dy = -dy
			}
			v += dy
		} else if fl&32 == 0 {
			if p+2 > len(d) {
				return nil
			}
			v += float64(int16(binary.BigEndian.Uint16(d[p:])))
			p += 2
		}
		ys[i] = v
	}
	var contours [][]fpoint
	s := 0
	for _, e := range endPts {
		if e < s {
			break
		}
		var c []fpoint
		for i := s; i <= e && i < nPts; i++ {
			c = append(c, fpoint{xs[i], ys[i], flags[i]&1 != 0})
		}
		contours = append(contours, c)
		s = e + 1
	}
	return contours
}

func (f *ttfFont) compositeContours(d []byte, depth int) [][]fpoint {
	var out [][]fpoint
	p := 0
	for {
		if p+4 > len(d) {
			break
		}
		flags := binary.BigEndian.Uint16(d[p:])
		gi := int(binary.BigEndian.Uint16(d[p+2:]))
		p += 4
		var dx, dy float64
		if flags&1 != 0 {
			if p+4 > len(d) {
				break
			}
			dx = float64(int16(binary.BigEndian.Uint16(d[p:])))
			dy = float64(int16(binary.BigEndian.Uint16(d[p+2:])))
			p += 4
		} else {
			if p+2 > len(d) {
				break
			}
			dx = float64(int8(d[p]))
			dy = float64(int8(d[p+1]))
			p += 2
		}
		a, b, c, dd := 1.0, 0.0, 0.0, 1.0
		f2 := func(off int) float64 { return float64(int16(binary.BigEndian.Uint16(d[off:]))) / 16384 }
		switch {
		case flags&8 != 0:
			if p+2 > len(d) {
				break
			}
			a = f2(p)
			dd = a
			p += 2
		case flags&0x40 != 0:
			if p+4 > len(d) {
				break
			}
			a = f2(p)
			dd = f2(p + 2)
			p += 4
		case flags&0x80 != 0:
			if p+8 > len(d) {
				break
			}
			a, b, c, dd = f2(p), f2(p+2), f2(p+4), f2(p+6)
			p += 8
		}
		sub := f.glyphContours(gi, depth+1)
		for _, cont := range sub {
			nc := make([]fpoint, len(cont))
			for i, pt := range cont {
				nc[i] = fpoint{a*pt.x + c*pt.y + dx, b*pt.x + dd*pt.y + dy, pt.onCurve}
			}
			out = append(out, nc)
		}
		if flags&0x20 == 0 {
			break
		}
	}
	return out
}

// rasterizer accumulates signed area coverage.
type rasterizer struct {
	w, h int
	acc  []float64
}

func newRasterizer(w, h int) *rasterizer {
	return &rasterizer{w: w, h: h, acc: make([]float64, w*h+1)}
}

func (r *rasterizer) line(x0, y0, x1, y1 float64) {
	if y0 == y1 {
		return
	}
	dir := 1.0
	if y0 > y1 {
		dir = -1.0
		x0, y0, x1, y1 = x1, y1, x0, y0
	}
	dxdy := (x1 - x0) / (y1 - y0)
	x := x0
	if y0 < 0 {
		x -= y0 * dxdy
	}
	yStart := int(math.Max(0, math.Floor(y0)))
	yEnd := int(math.Min(float64(r.h), math.Ceil(y1)))
	for y := yStart; y < yEnd; y++ {
		linestart := y * r.w
		dy := math.Min(float64(y+1), y1) - math.Max(float64(y), y0)
		xnext := x + dxdy*dy
		d := dy * dir
		xa, xb := x, xnext
		if xa > xb {
			xa, xb = xb, xa
		}
		x0floor := math.Floor(xa)
		x0i := int(x0floor)
		x1ceil := math.Ceil(xb)
		x1i := int(x1ceil)
		if x0i < 0 {
			// contribution entirely left of the canvas affects everything to the right
			if x1i <= 0 {
				r.add(linestart, d)
				x = xnext
				continue
			}
		}
		if x1i <= x0i+1 {
			xmf := 0.5*(xa+xb) - x0floor
			r.add(linestart+x0i, d-d*xmf)
			r.add(linestart+x0i+1, d*xmf)
		} else {
			s := 1 / (xb - xa)
			x0f := xa - x0floor
			a0 := 0.5 * s * (1 - x0f) * (1 - x0f)
			x1f := xb - x1ceil + 1
			am := 0.5 * s * x1f * x1f
			r.add(linestart+x0i, d*a0)
			if x1i == x0i+2 {
				r.add(linestart+x0i+1, d*(1-a0-am))
			} else {
				a1 := s * (1.5 - x0f)
				r.add(linestart+x0i+1, d*(a1-a0))
				for xi := x0i + 2; xi < x1i-1; xi++ {
					r.add(linestart+xi, d*s)
				}
				a2 := a1 + float64(x1i-x0i-3)*s
				r.add(linestart+x1i-1, d*(1-a2-am))
			}
			r.add(linestart+x1i, d*am)
		}
		x = xnext
	}
}

func (r *rasterizer) add(i int, v float64) {
	if i < 0 {
		i = 0
	}
	if i >= len(r.acc) {
		return
	}
	r.acc[i] += v
}

func (r *rasterizer) quad(x0, y0, cx, cy, x1, y1 float64) {
	devx := x0 - 2*cx + x1
	devy := y0 - 2*cy + y1
	devsq := devx*devx + devy*devy
	n := 1
	if devsq >= 0.333 {
		tol := 3.0
		n = int(math.Min(math.Ceil(math.Sqrt(math.Sqrt(tol*devsq))), 64))
	}
	px, py := x0, y0
	for i := 1; i <= n; i++ {
		t := float64(i) / float64(n)
		mt := 1 - t
		nx := mt*mt*x0 + 2*mt*t*cx + t*t*x1
		ny := mt*mt*y0 + 2*mt*t*cy + t*t*y1
		r.line(px, py, nx, ny)
		px, py = nx, ny
	}
}

// coverage returns the per-pixel coverage in [0,1].
func (r *rasterizer) coverage() []float64 {
	out := make([]float64, r.w*r.h)
	acc := 0.0
	for i := 0; i < r.w*r.h; i++ {
		acc += r.acc[i]
		v := math.Abs(acc)
		if v > 1 {
			v = 1
		}
		out[i] = v
	}
	return out
}

// drawString draws s (normally a single character) into the cell at
// (ox, oy) of size cellW x cellH using colour col.
func (f *ttfFont) drawString(img *image.NRGBA, s string, ox, oy, cellW, cellH float64, col color.NRGBA) {
	if f == nil || cellW <= 0 || cellH <= 0 {
		return
	}
	size := cellH * 0.8 // pixels per em
	scale := size / f.unitsPerEm
	baseline := oy + cellH*0.78
	penX := ox
	for _, ch := range s {
		g := f.glyphIndex(ch)
		adv := f.advance(g) * scale
		// centre glyph horizontally in the cell
		gx := penX + (cellW-adv)/2
		f.drawGlyph(img, g, gx, baseline, scale, col)
		penX += cellW
	}
}

func (f *ttfFont) drawGlyph(img *image.NRGBA, g int, x, baseline, scale float64, col color.NRGBA) {
	contours := f.glyphContours(g, 0)
	if len(contours) == 0 {
		return
	}
	// bounding box in pixels
	minX, minY := math.Inf(1), math.Inf(1)
	maxX, maxY := math.Inf(-1), math.Inf(-1)
	for _, c := range contours {
		for _, p := range c {
			px := x + p.x*scale
			py := baseline - p.y*scale
			minX = math.Min(minX, px)
			maxX = math.Max(maxX, px)
			minY = math.Min(minY, py)
			maxY = math.Max(maxY, py)
		}
	}
	bx0 := int(math.Floor(minX)) - 1
	by0 := int(math.Floor(minY)) - 1
	bx1 := int(math.Ceil(maxX)) + 1
	by1 := int(math.Ceil(maxY)) + 1
	w, h := bx1-bx0, by1-by0
	if w <= 0 || h <= 0 || w > 4096 || h > 4096 {
		return
	}
	ras := newRasterizer(w, h)
	tx := func(p fpoint) (float64, float64) {
		return x + p.x*scale - float64(bx0), baseline - p.y*scale - float64(by0)
	}
	for _, c := range contours {
		n := len(c)
		if n == 0 {
			continue
		}
		// find a starting on-curve point
		startIdx := -1
		for i, p := range c {
			if p.onCurve {
				startIdx = i
				break
			}
		}
		var sx, sy float64
		if startIdx < 0 {
			// all off-curve: start at midpoint of last and first
			ax, ay := tx(c[n-1])
			bx, by := tx(c[0])
			sx, sy = (ax+bx)/2, (ay+by)/2
			startIdx = 0
		} else {
			sx, sy = tx(c[startIdx])
		}
		cx, cy := sx, sy
		var ctrlX, ctrlY float64
		haveCtrl := false
		for k := 1; k <= n; k++ {
			p := c[(startIdx+k)%n]
			px, py := tx(p)
			if p.onCurve {
				if haveCtrl {
					ras.quad(cx, cy, ctrlX, ctrlY, px, py)
					haveCtrl = false
				} else {
					ras.line(cx, cy, px, py)
				}
				cx, cy = px, py
			} else {
				if haveCtrl {
					mx, my := (ctrlX+px)/2, (ctrlY+py)/2
					ras.quad(cx, cy, ctrlX, ctrlY, mx, my)
					cx, cy = mx, my
				}
				ctrlX, ctrlY = px, py
				haveCtrl = true
			}
		}
		if haveCtrl {
			ras.quad(cx, cy, ctrlX, ctrlY, sx, sy)
		} else if cx != sx || cy != sy {
			ras.line(cx, cy, sx, sy)
		}
	}
	cov := ras.coverage()
	for yy := 0; yy < h; yy++ {
		py := by0 + yy
		if py < 0 || py >= img.Bounds().Dy() {
			continue
		}
		for xx := 0; xx < w; xx++ {
			px := bx0 + xx
			if px < 0 || px >= img.Bounds().Dx() {
				continue
			}
			a := cov[yy*w+xx]
			if a <= 0 {
				continue
			}
			blendPixel(img, px, py, col, a)
		}
	}
}

// blendPixel composites col with coverage a over the destination pixel
// (source-over in non-premultiplied space).
func blendPixel(img *image.NRGBA, x, y int, col color.NRGBA, a float64) {
	i := img.PixOffset(x, y)
	sa := a * float64(col.A) / 255
	da := float64(img.Pix[i+3]) / 255
	oa := sa + da*(1-sa)
	if oa <= 0 {
		return
	}
	blend := func(s, d uint8) uint8 {
		v := (float64(s)*sa + float64(d)*da*(1-sa)) / oa
		return uint8(math.Round(v))
	}
	img.Pix[i] = blend(col.R, img.Pix[i])
	img.Pix[i+1] = blend(col.G, img.Pix[i+1])
	img.Pix[i+2] = blend(col.B, img.Pix[i+2])
	img.Pix[i+3] = uint8(math.Round(oa * 255))
}

