type crossing struct {
	x   float64
	dir int
}

// coverage returns the per-pixel coverage in [0,1].
func (r *rasterizer) coverage() []float64 {
	const sub = 5
	out := make([]float64, r.w*r.h)
	var xs []crossing
	for y := 0; y < r.h; y++ {
