					dir = -1
				}
				if sy < ymin || sy >= ymax {
					continue
				}
				x := e.x0 + (sy-e.y0)*(e.x1-e.x0)/(e.y1-e.y0)
				xs = append(xs, crossing{x, dir})
			}
			if len(xs) < 2 {
				continue
			}
			// insertion sort (small arrays)
			for i := 1; i < len(xs); i++ {
				for j := i; j > 0 && xs[j-1].x > xs[j].x; j-- {
					xs[j-1], xs[j] = xs[j], xs[j-1]
				}
			}
			wind := 0
			for i := 0; i < len(xs)-1; i++ {
				wind += xs[i].dir
				if wind == 0 {
					continue
				}
				xa, xb := xs[i].x, xs[i+1].x
				if xb <= xa {
					continue
				}
				if xa < 0 {
