{"command":"cd /workspace && cat > bmp.go <<'EOF'
package main

import (
	"errors"
	"image"
	"image/color"
	"io"
)

// Minimal BMP decoder registered with the image package.

type bmpFormatError string

func (e bmpFormatError) Error() string { return "bmp: unsupported feature: " + string(e) }

var errBmpCorrupt = errors.New("bmp: invalid format")

func init() {
	image.RegisterFormat("bmp", "BM????\x00\x00\x00\x00", bmpDecode, bmpDecodeConfig)
}

func readFullBytes(r io.Reader, n int) ([]byte, error) {
	b := make([]byte, n)
	if _, err := io.ReadFull(r, b); err != nil {
		return nil, err
	}
	return b, nil
}

func u16le(b []byte) uint32 { return uint32(b[0]) | uint32(b[1])<<8 }
func u32le(b []byte) uint32 {
	return uint32(b[0]) | uint32(b[1])<<8 | uint32(b[2])<<16 | uint32(b[3])<<24
}

type bmpHeader struct {
	width, height int
	topDown       bool
	bpp           int
	palette       color.Palette
	offset        int
	alpha         bool
}

func bmpReadHeader(r io.Reader) (*bmpHeader, error) {
	const fileHeaderLen = 14
	b, err := readFullBytes(r, fileHeaderLen+4)
	if err != nil {
		if err == io.EOF {
			err = io.ErrUnexpectedEOF
		}
		return nil, err
	}
	if string(b[:2]) != "BM" {
		return nil, errBmpCorrupt
	}
	offset := u32le(b[10:14])
	infoLen := u32le(b[14:18])
	if infoLen != 40 && infoLen != 52 && infoLen != 56 && infoLen != 108 && infoLen != 124 {
		return nil, bmpFormatError("info header length")
	}
	rest, err := readFullBytes(r, int(infoLen)-4)
	if err != nil {
		if err == io.EOF {
			err = io.ErrUnexpectedEOF
		}
		return nil, err
	}
	b = append(b, rest...)
	width := int(int32(u32le(b[18:22])))
	height := int(int32(u32le(b[22:26])))
	topDown := false
	if height < 0 {
		height, topDown = -height, true
	}
	if width < 0 || height < 0 {
		return nil, bmpFormatError("negative dimensions")
	}
	planes, bpp, compression := u16le(b[26:28]), u16le(b[28:30]), u32le(b[30:34])
	if compression == 3 && infoLen > 40 {
		// bitfields: accept only the standard masks
		rmask, gmask, bmask := u32le(b[54:58]), u32le(b[58:62]), u32le(b[62:66])
		if (bpp == 24 || bpp == 32) && rmask == 0xff0000 && gmask == 0xff00 && bmask == 0xff {
			compression = 0
		}
	}
	if planes != 1 || compression != 0 {
		return nil, bmpFormatError("compression or planes")
	}
	alpha := false
	if infoLen > 40 && bpp == 32 {
		amask := u32le(b[66:70])
		alpha = amask == 0xff000000
	}
	h := &bmpHeader{width: width, height: height, topDown: topDown, bpp: int(bpp), offset: int(offset), alpha: alpha}
	switch bpp {
	case 1, 4, 8:
		colors := u32le(b[46:50])
		if colors == 0 || colors > 1<<bpp {
			colors = 1 << bpp
		}
		if offset != fileHeaderLen+infoLen+colors*4 {
			return nil, bmpFormatError("palette offset")
		}
		pal, err := readFullBytes(r, int(colors)*4)
		if err != nil {
			if err == io.EOF {
				err = io.ErrUnexpectedEOF
			}
			return nil, err
		}
		h.palette = make(color.Palette, 1<<bpp)
		for i := range h.palette {
			h.palette[i] = color.RGBA{0, 0, 0, 0xff}
		}
		for i := 0; i < int(colors); i++ {
			h.palette[i] = color.RGBA{pal[4*i+2], pal[4*i+1], pal[4*i+0], 0xff}
		}
		return h, nil
	case 24, 32:
		if offset != fileHeaderLen+infoLen {
			return nil, bmpFormatError("pixel offset")
		}
		return h, nil
	}
	return nil, bmpFormatError("bit depth")
}

func bmpDecodeConfig(r io.Reader) (image.Config, error) {
	h, err := bmpReadHeader(r)
	if err != nil {
		return image.Config{}, err
	}
	var cm color.Model
	switch h.bpp {
	case 1, 4, 8:
		cm = h.palette
	case 24:
		cm = color.RGBAModel
	case 32:
		if h.alpha {
			cm = color.NRGBAModel
		} else {
			cm = color.RGBAModel
		}
	}
	return image.Config{ColorModel: cm, Width: h.width, Height: h.height}, nil
}

func bmpDecode(r io.Reader) (image.Image, error) {
	h, err := bmpReadHeader(r)
	if err != nil {
		return nil, err
	}
	if h.width == 0 || h.height == 0 {
		return image.NewRGBA(image.Rect(0, 0, h.width, h.height)), nil
	}
	switch h.bpp {
	case 1, 4, 8:
		return bmpDecodePaletted(r, h)
	case 24:
		return bmpDecodeRGB(r, h)
	default:
		return bmpDecodeRGBA(r, h)
	}
}

func bmpRows(h *bmpHeader) (start, step int) {
	if h.topDown {
		return 0, 1
	}
	return h.height - 1, -1
}

func bmpDecodePaletted(r io.Reader, h *bmpHeader) (image.Image, error) {
	img := image.NewPaletted(image.Rect(0, 0, h.width, h.height), h.palette)
	rowBits := h.width * h.bpp
	rowLen := ((rowBits + 31) / 32) * 4
	row := make([]byte, rowLen)
	y, step := bmpRows(h)
	for i := 0; i < h.height; i++ {
		if _, err := io.ReadFull(r, row); err != nil {
			if err == io.EOF {
				err = io.ErrUnexpectedEOF
			}
			return nil, err
		}
		p := img.Pix[y*img.Stride : y*img.Stride+h.width]
		switch h.bpp {
		case 8:
			copy(p, row[:h.width])
		case 4:
			for x := 0; x < h.width; x++ {
				v := row[x/2]
				if x%2 == 0 {
					p[x] = v >> 4
				} else {
					p[x] = v & 0x0f
				}
			}
		case 1:
			for x := 0; x < h.width; x++ {
				p[x] = (row[x/8] >> (7 - uint(x%8))) & 1
			}
		}
		y += step
	}
	return img, nil
}

func bmpDecodeRGB(r io.Reader, h *bmpHeader) (image.Image, error) {
	img := image.NewRGBA(image.Rect(0, 0, h.width, h.height))
	rowLen := ((h.width*24 + 31) / 32) * 4
	row := make([]byte, rowLen)
	y, step := bmpRows(h)
	for i := 0; i < h.height; i++ {
		if _, err := io.ReadFull(r, row); err != nil {
			if err == io.EOF {
				err = io.ErrUnexpectedEOF
			}
			return nil, err
		}
		p := img.Pix[y*img.Stride : y*img.Stride+h.width*4]
		for x, j := 0, 0; x < h.width*4; x, j = x+4, j+3 {
			p[x+0] = row[j+2]
			p[x+1] = row[j+1]
			p[x+2] = row[j+0]
			p[x+3] = 0xff
		}
		y += step
	}
	return img, nil
}

func bmpDecodeRGBA(r io.Reader, h *bmpHeader) (image.Image, error) {
	rowLen := h.width * 4
	y, step := bmpRows(h)
	if h.alpha {
		img := image.NewNRGBA(image.Rect(0, 0, h.width, h.height))
		for i := 0; i < h.height; i++ {
			p := img.Pix[y*img.Stride : y*img.Stride+rowLen]
			if _, err := io.ReadFull(r, p); err != nil {
				if err == io.EOF {
					err = io.ErrUnexpectedEOF
				}
				return nil, err
			}
			for x := 0; x < rowLen; x += 4 {
				p[x+0], p[x+2] = p[x+2], p[x+0]
			}
			y += step
		}
		return img, nil
	}
	img := image.NewRGBA(image.Rect(0, 0, h.width, h.height))
	for i := 0; i < h.height; i++ {
		p := img.Pix[y*img.Stride : y*img.Stride+rowLen]
		if _, err := io.ReadFull(r, p); err != nil {
			if err == io.EOF {
				err = io.ErrUnexpectedEOF
			}
			return nil, err
		}
		for x := 0; x < rowLen; x += 4 {
			p[x+0], p[x+2] = p[x+2], p[x+0]
			p[x+3] = 0xff
		}
		y += step
	}
	return img, nil
}
EOF
go build -o executable . && echo ok"}

