		return bmpDecodeRGBA(r, h)
	}
}

func bmpRows(h *bmpHeader) (start, step int) {
	if h.topDown {
		return 0, 1
	}
	return h.height - 1, -1
}

func bmpDecodePaletted(r io.Reader, h *bmpHeader) (image.Image, error) {
	img := image.NewPaletted(image.Rect(0, 0, h.width, h.height), h.palette)
	rowBits := h.width * h.bpp
	rowLen := ((rowBits + 31) / 32) * 4
	row := make([]byte, rowLen)
	y, step := bmpRows(h)
	for i := 0; i < h.height; i++ {
		if _, err := io.ReadFull(r, row); err != nil {
			if err == io.EOF {
				err = io.ErrUnexpectedEOF
			}
			return nil, err
		}
		p := img.Pix[y*img.Stride : y*img.Stride+h.width]
		switch h.bpp {
		case 8:
			copy(p, row[:h.width])
		case 4:
			for x := 0; x < h.width; x++ {
				v := row[x/2]
				if x%2 == 0 {
					p[x] = v >> 4
				} else {
					p[x] = v & 0x0f
				}
			}
		case 1:
			for x := 0; x < h.width; x++ {
				p[x] = (row[x/8] >> (7 - uint(x%8))) & 1
			}
		}
		y += step
	}
	return img, nil
}

func bmpDecodeRGB(r io.Reader, h *bmpHeader) (image.Image, error) {
	img := image.NewRGBA(image.Rect(0, 0, h.width, h.height))
	rowLen := ((h.width*24 + 31) / 32) * 4
	row := make([]byte, rowLen)
	y, step := bmpRows(h)
	for i := 0; i < h.height; i++ {
		if _, err := io.ReadFull(r, row); err != nil {
			if err == io.EOF {
				err = io.ErrUnexpectedEOF
			}
			return nil, err
		}
		p := img.Pix[y*img.Stride : y*img.Stride+h.width*4]
		for x, j := 0, 0; x < h.width*4; x, j = x+4, j+3 {
			p[x+0] = row[j+2]
			p[x+1] = row[j+1]
			p[x+2] = row[j+0]
			p[x+3] = 0xff
		}
		y += step
	}
	return img, nil
}

func bmpDecodeRGBA(r io.Reader, h *bmpHeader) (image.Image, error) {
	rowLen := h.width * 4
	y, step := bmpRows(h)
