			if idx < len(counts) {
				n = int64(counts[idx])
			}
			switch d.firstVal(tCompression) {
			case 0, 1:
				d.buf = make([]byte, n)
				if _, err := d.r.ReadAt(d.buf, offset); err != nil {
					return nil, errTiffNoPixels
				}
			case 5:
				raw := make([]byte, n)
				if _, err := d.r.ReadAt(raw, offset); err != nil {
					return nil, errTiffNoPixels
				}
				d.buf, err = tiffLZWDecode(raw)
				if err != nil {
					return nil, err
				}
			case 8, 32946:
				raw := make([]byte, n)
				if _, err := d.r.ReadAt(raw, offset); err != nil {
					return nil, errTiffNoPixels
				}
				zr, err := zlib.NewReader(bytes.NewReader(raw))
				if err != nil {
					return nil, err
				}
				d.buf, err = io.ReadAll(zr)
				zr.Close()
				if err != nil {
					return nil, err
				}
			case 32773:
				raw := make([]byte, n)
				if _, err := d.r.ReadAt(raw, offset); err != nil {
					return nil, errTiffNoPixels
				}
				d.buf = packBitsDecode(raw)
			default:
				return nil, tiffUnsupportedError("compression")
			}
			d.off = 0
			d.flushBits()
			xmin := i * blockW
			ymin := j * blockH
			if err := d.decodeBlock(img, xmin, ymin, xmin+blkW, ymin+blkH); err != nil {
				return nil, err
			}
		}
	}
	return img, nil
}

func packBitsDecode(src []byte) []byte {
	var dst []byte
	for i := 0; i < len(src); {
		n := int(int8(src[i]))
		i++
		switch {
		case n >= 0:
			end := i + n + 1
			if end > len(src) {
				end = len(src)
			}
			dst = append(dst, src[i:end]...)
			i = end
		case n == -128:
		default:
			if i < len(src) {
				b := src[i]
				i++
				for k := 0; k < 1-n; k++ {
					dst = append(dst, b)
				}
			}
		}
	}
	return dst
}

// tiffLZWDecode implements the MSB-first LZW variant used by TIFF (with the
// "early change" code width switch).
func tiffLZWDecode(src []byte) ([]byte, error) {
	const (
		clearCode = 256
		eoiCode   = 257
	)
	var out []byte
	var bitBuf uint32
	var bitCnt uint
	pos := 0
	width := uint(9)
	prefix := make([]int, 4096)
	suffix := make([]byte, 4096)
	lengths := make([]int, 4096)
	for i := 0; i < 256; i++ {
		prefix[i] = -1
		suffix[i] = byte(i)
		lengths[i] = 1
	}
	next := 258
	prev := -1
	decode := func(code int) []byte {
		l := lengths[code]
		b := make([]byte, l)
		for i := l - 1; i >= 0; i-- {
			b[i] = suffix[code]
			code = prefix[code]
		}
		return b
	}
	for {
		for bitCnt < width {
			if pos >= len(src) {
				return out, nil
			}
			bitBuf = bitBuf<<8 | uint32(src[pos])
			pos++
			bitCnt += 8
		}
		code := int((bitBuf >> (bitCnt - width)) & (1<<width - 1))
		bitCnt -= width
		if code == eoiCode {
			return out, nil
		}
		if code == clearCode {
			next = 258
			width = 9
			prev = -1
			continue
		}
		var entry []byte
		if code < next {
			entry = decode(code)
			if prev >= 0 && next < 4096 {
				prefix[next] = prev
				suffix[next] = entry[0]
				lengths[next] = lengths[prev] + 1
				next++
			}
		} else if code == next && prev >= 0 && next < 4096 {
			first := decode(prev)[0]
			prefix[next] = prev
			suffix[next] = first
			lengths[next] = lengths[prev] + 1
			next++
			entry = decode(code)
		} else {
			return nil, errors.New("tiff: invalid format: bad LZW code")
		}
		out = append(out, entry...)
		prev = code
		if next+1 >= 1<<width && width < 12 {
			width++
		}
	}
}
