cd /workspace && cat > tiff.go <<'EOF'
package main

import (
	"bytes"
	"compress/zlib"
	"encoding/binary"
	"errors"
	"image"
	"image/color"
	"io"
)

// A baseline TIFF decoder (strips/tiles; none, LZW, Deflate and PackBits
// compression; bilevel, grayscale, paletted and RGB(A) images).

type tiffFormatError string

func (e tiffFormatError) Error() string { return "tiff: invalid format: " + string(e) }

type tiffUnsupportedError string

func (e tiffUnsupportedError) Error() string { return "tiff: unsupported feature: " + string(e) }

var errTiffNoPixels = tiffFormatError("no pixel data")

func init() {
	image.RegisterFormat("tiff", "II\x2A\x00", tiffDecode, tiffDecodeConfig)
	image.RegisterFormat("tiff", "MM\x00\x2A", tiffDecode, tiffDecodeConfig)
}

const (
	tWidth        = 256
	tLength       = 257
	tBitsPerSmp   = 258
	tCompression  = 259
	tPhotometric  = 262
	tStripOffsets = 273
	tSamplesPP    = 277
	tRowsPerStrip = 278
	tStripBytes   = 279
	tPredictor    = 317
	tColorMap     = 320
	tTileWidth    = 322
	tTileLength   = 323
	tTileOffsets  = 324
	tTileBytes    = 325
	tExtraSamples = 338
	tSampleFormat = 339
)

type tiffDecoder struct {
	r        io.ReaderAt
	bo       binary.ByteOrder
	features map[int][]uint
	palette  color.Palette
	mode     int // 0 bilevel,1 gray,2 gray-inverted,3 paletted,4 rgb,5 rgba,6 nrgba
	bpp      uint
	spp      uint
	width    int
	height   int
	buf      []byte
	off      int
	v        uint32
	nbits    uint
}

var tiffTypeLen = [...]uint32{0, 1, 1, 2, 4, 8, 1, 1, 2, 4, 8, 4, 8}

func (d *tiffDecoder) readIFD(p []byte) error {
	tag := d.bo.Uint16(p[0:2])
	typ := d.bo.Uint16(p[2:4])
	count := d.bo.Uint32(p[4:8])
	if typ == 0 || int(typ) >= len(tiffTypeLen) {
		return nil // unknown type, ignore
	}
	size := tiffTypeLen[typ] * count
	var raw []byte
	if size > 4 {
		off := d.bo.Uint32(p[8:12])
		raw = make([]byte, size)
		if _, err := d.r.ReadAt(raw, int64(off)); err != nil {
			return err
		}
	} else {
		raw = p[8 : 8+size]
	}
	switch tag {
	case tBitsPerSmp, tExtraSamples, tPhotometric, tCompression, tPredictor, tStripOffsets, tStripBytes, tRowsPerStrip, tTileWidth, tTileLength, tTileOffsets, tTileBytes, tWidth, tLength, tColorMap, tSamplesPP, tSampleFormat:
		vals := make([]uint, count)
		for i := range vals {
			switch typ {
			case 1, 6, 7:
				vals[i] = uint(raw[i])
			case 3, 8:
				vals[i] = uint(d.bo.Uint16(raw[2*i:]))
			case 4, 9:
				vals[i] = uint(d.bo.Uint32(raw[4*i:]))
			default:
				return tiffUnsupportedError("tag value type")
			}
		}
		d.features[int(tag)] = vals
	}
	return nil
}

func (d *tiffDecoder) firstVal(tag int) uint {
	f := d.features[tag]
	if len(f) == 0 {
		return 0
	}
	return f[0]
}

func newTiffDecoder(r io.Reader) (*tiffDecoder, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	ra := bytes.NewReader(data)
	d := &tiffDecoder{r: ra, features: map[int][]uint{}}
	if len(data) < 8 {
		return nil, tiffFormatError("malformed header")
	}
	switch string(data[0:4]) {
	case "II\x2A\x00":
		d.bo = binary.LittleEndian
	case "MM\x00\x2A":
		d.bo = binary.BigEndian
	default:
		return nil, tiffFormatError("malformed header")
	}
	ifdOffset := int64(d.bo.Uint32(data[4:8]))
	var p [2]byte
	if _, err := ra.ReadAt(p[:], ifdOffset); err != nil {
		return nil, tiffFormatError("malformed header")
	}
	n := int(d.bo.Uint16(p[:]))
	ifd := make([]byte, n*12)
	if _, err := ra.ReadAt(ifd, ifdOffset+2); err != nil {
		return nil, tiffFormatError("malformed header")
	}
	for i := 0; i < n; i++ {
		if err := d.readIFD(ifd[i*12 : (i+1)*12]); err != nil {
			return nil, tiffFormatError("malformed header")
		}
	}
	d.width = int(d.firstVal(tWidth))
	d.height = int(d.firstVal(tLength))
	if d.width <= 0 || d.height <= 0 {
		return nil, tiffFormatError("image dimensions")
	}
	if bps, ok := d.features[tBitsPerSmp]; ok {
		d.bpp = bps[0]
		for _, b := range bps {
			if b != d.bpp {
				return tiffUnsupported(d, "varying bits per sample")
			}
		}
	} else {
		d.bpp = 1
	}
	switch d.bpp {
	case 0:
		return nil, tiffFormatError("BitsPerSample must not be 0")
	case 1, 8, 16:
	default:
		return tiffUnsupported(d, "BitsPerSample")
	}
	if sf, ok := d.features[tSampleFormat]; ok {
		for _, v := range sf {
			if v != 1 {
				return tiffUnsupported(d, "sample format")
			}
		}
	}
	d.spp = d.firstVal(tSamplesPP)
	if d.spp == 0 {
		d.spp = 1
	}
	switch d.firstVal(tPhotometric) {
	case 2: // RGB
		if d.spp == 3 {
			d.mode = 4
		} else if d.spp == 4 {
			es := d.features[tExtraSamples]
			if len(es) == 1 && es[0] == 1 {
				d.mode = 5
			} else {
				d.mode = 6
			}
		} else {
			return tiffFormatError("wrong number of samples for RGB")
		}
	case 3: // paletted
		d.mode = 3
		cm, ok := d.features[tColorMap]
		if !ok || len(cm)%3 != 0 {
			return tiffFormatError("bad color map")
		}
		numColors := len(cm) / 3
		if numColors <= 0 || numColors > 256 {
			return tiffUnsupported(d, "color map length")
		}
		d.palette = make(color.Palette, numColors)
		for i := range d.palette {
			d.palette[i] = color.RGBA64{uint16(cm[i]), uint16(cm[i+numColors]), uint16(cm[i+2*numColors]), 0xffff}
		}
	case 0: // white is zero
		if d.bpp == 1 {
			d.mode = 0
		} else {
			d.mode = 2
		}
	case 1: // black is zero
		if d.bpp == 1 {
			d.mode = 0
		} else {
			d.mode = 1
		}
	default:
		return tiffUnsupported(d, "color model")
	}
	return d, nil
}

func tiffUnsupported(d *tiffDecoder, s string) (*tiffDecoder, error) {
	return nil, tiffUnsupportedError(s)
}

func (d *tiffDecoder) readBits(n uint) uint32 {
	for d.nbits < n {
		d.v <<= 8
		if d.off < len(d.buf) {
			d.v |= uint32(d.buf[d.off])
		}
		d.off++
		d.nbits += 8
	}
	d.nbits -= n
	rv := d.v >> d.nbits
	d.v &^= rv << d.nbits
	return rv
}

func (d *tiffDecoder) flushBits() {
	d.v = 0
	d.nbits = 0
}

// decodeBlock decodes the already decompressed block in d.buf into dst.
func (d *tiffDecoder) decodeBlock(dst image.Image, xmin, ymin, xmax, ymax int) error {
	rMaxX := xmax
	if rMaxX > d.width {
		rMaxX = d.width
	}
	rMaxY := ymax
	if rMaxY > d.height {
		rMaxY = d.height
	}
	if d.firstVal(tPredictor) == 2 {
		if d.bpp == 16 {
			bpp := int(d.spp) * 2
			rowLen := (xmax - xmin) * bpp
			for y := ymin; y < rMaxY; y++ {
				off0 := (y - ymin) * rowLen
				for x := bpp; x < rowLen && off0+x+1 < len(d.buf); x += 2 {
					v0 := d.bo.Uint16(d.buf[off0+x-bpp:])
					v1 := d.bo.Uint16(d.buf[off0+x:])
					d.bo.PutUint16(d.buf[off0+x:], v1+v0)
				}
			}
		} else if d.bpp == 8 {
			bpp := int(d.spp)
			rowLen := (xmax - xmin) * bpp
			for y := ymin; y < rMaxY; y++ {
				off0 := (y - ymin) * rowLen
				for x := bpp; x < rowLen && off0+x < len(d.buf); x++ {
					d.buf[off0+x] += d.buf[off0+x-bpp]
				}
			}
		}
	}
	switch d.mode {
	case 1, 2: // gray
		if d.bpp == 16 {
			img := dst.(*image.Gray16)
			for y := ymin; y < rMaxY; y++ {
				for x := xmin; x < rMaxX; x++ {
					if d.off+2 > len(d.buf) {
						return errTiffNoPixels
					}
					v := d.bo.Uint16(d.buf[d.off:])
					d.off += 2
					if d.mode == 2 {
						v = 0xffff - v
					}
					img.SetGray16(x, y, color.Gray16{v})
				}
			}
		} else {
			img := dst.(*image.Gray)
			max := uint32(1)<<d.bpp - 1
			for y := ymin; y < rMaxY; y++ {
				for x := xmin; x < rMaxX; x++ {
					if d.off >= len(d.buf) && d.nbits < d.bpp {
						return errTiffNoPixels
					}
					v := d.readBits(d.bpp)
					v = v * 0xff / max
					if d.mode == 2 {
						v = 0xff - v
					}
					img.SetGray(x, y, color.Gray{uint8(v)})
				}
				d.flushBits()
			}
		}
	case 3: // paletted
		img := dst.(*image.Paletted)
		for y := ymin; y < rMaxY; y++ {
			for x := xmin; x < rMaxX; x++ {
				if d.off >= len(d.buf) && d.nbits < d.bpp {
					return errTiffNoPixels
				}
				img.SetColorIndex(x, y, uint8(d.readBits(d.bpp)))
			}
			d.flushBits()
		}
	case 4: // rgb
		if d.bpp == 16 {
			img := dst.(*image.RGBA64)
			for y := ymin; y < rMaxY; y++ {
				for x := xmin; x < rMaxX; x++ {
					if d.off+6 > len(d.buf) {
						return errTiffNoPixels
					}
					r := d.bo.Uint16(d.buf[d.off:])
					g := d.bo.Uint16(d.buf[d.off+2:])
					b := d.bo.Uint16(d.buf[d.off+4:])
					d.off += 6
					img.SetRGBA64(x, y, color.RGBA64{r, g, b, 0xffff})
				}
			}
		} else {
			img := dst.(*image.RGBA)
			for y := ymin; y < rMaxY; y++ {
				min := img.PixOffset(xmin, y)
				max := img.PixOffset(rMaxX, y)
				off := (y - ymin) * (xmax - xmin) * 3
				for i := min; i < max; i += 4 {
					if off+3 > len(d.buf) {
						return errTiffNoPixels
					}
					img.Pix[i+0] = d.buf[off+0]
					img.Pix[i+1] = d.buf[off+1]
					img.Pix[i+2] = d.buf[off+2]
					img.Pix[i+3] = 0xff
					off += 3
				}
			}
		}
	case 5, 6: // rgba / nrgba
		if d.bpp == 16 {
			for y := ymin; y < rMaxY; y++ {
				for x := xmin; x < rMaxX; x++ {
					if d.off+8 > len(d.buf) {
						return errTiffNoPixels
					}
					r := d.bo.Uint16(d.buf[d.off:])
					g := d.bo.Uint16(d.buf[d.off+2:])
					b := d.bo.Uint16(d.buf[d.off+4:])
					a := d.bo.Uint16(d.buf[d.off+6:])
					d.off += 8
					if d.mode == 5 {
						dst.(*image.RGBA64).SetRGBA64(x, y, color.RGBA64{r, g, b, a})
					} else {
						dst.(*image.NRGBA64).SetNRGBA64(x, y, color.NRGBA64{r, g, b, a})
					}
				}
			}
		} else {
			var pix []byte
			var stride int
			if d.mode == 5 {
				img := dst.(*image.RGBA)
				pix, stride = img.Pix, img.Stride
			} else {
				img := dst.(*image.NRGBA)
				pix, stride = img.Pix, img.Stride
			}
			for y := ymin; y < rMaxY; y++ {
				min := y*stride + xmin*4
				max := y*stride + rMaxX*4
				off := (y - ymin) * (xmax - xmin) * 4
				if off+(max-min) > len(d.buf) {
					return errTiffNoPixels
				}
				copy(pix[min:max], d.buf[off:off+(max-min)])
			}
		}
	case 0: // bilevel
		img := dst.(*image.Gray)
		white := d.firstVal(tPhotometric) == 0
		for y := ymin; y < rMaxY; y++ {
			for x := xmin; x < rMaxX; x++ {
				if d.off >= len(d.buf) && d.nbits < 1 {
					return errTiffNoPixels
				}
				v := uint8(d.readBits(1))
				if white {
					v = 1 - v
				}
				img.SetGray(x, y, color.Gray{v * 0xff})
			}
			d.flushBits()
		}
	}
	return nil
}

func tiffDecodeConfig(r io.Reader) (image.Config, error) {
	d, err := newTiffDecoder(r)
	if err != nil {
		return image.Config{}, err
	}
	return image.Config{ColorModel: d.colorModel(), Width: d.width, Height: d.height}, nil
}

func (d *tiffDecoder) colorModel() color.Model {
	switch d.mode {
	case 0:
		return color.GrayModel
	case 1, 2:
		if d.bpp == 16 {
			return color.Gray16Model
		}
		return color.GrayModel
	case 3:
		return d.palette
	case 4, 5:
		if d.bpp == 16 {
			return color.RGBA64Model
		}
		return color.RGBAModel
	default:
		if d.bpp == 16 {
			return color.NRGBA64Model
		}
		return color.NRGBAModel
	}
}

func tiffDecode(r io.Reader) (image.Image, error) {
	d, err := newTiffDecoder(r)
	if err != nil {
		return nil, err
	}
	rect := image.Rect(0, 0, d.width, d.height)
	var img image.Image
	switch d.mode {
	case 0:
		img = image.NewGray(rect)
	case 1, 2:
		if d.bpp == 16 {
			img = image.NewGray16(rect)
		} else {
			img = image.NewGray(rect)
		}
	case 3:
		img = image.NewPaletted(rect, d.palette)
	case 4, 5:
		if d.bpp == 16 {
			img = image.NewRGBA64(rect)
		} else {
			img = image.NewRGBA(rect)
		}
	default:
		if d.bpp == 16 {
			img = image.NewNRGBA64(rect)
		} else {
			img = image.NewNRGBA(rect)
		}
	}

	blockPadding := false
	blockW, blockH := d.width, d.height
	blocksAcross, blocksDown := 1, 1
	var offsets, counts []uint
	if _, ok := d.features[tTileWidth]; ok {
		blockPadding = true
		blockW = int(d.firstVal(tTileWidth))
		blockH = int(d.firstVal(tTileLength))
		if blockW <= 0 || blockH <= 0 {
			return nil, tiffUnsupportedError("tile dimensions")
		}
		blocksAcross = (d.width + blockW - 1) / blockW
		blocksDown = (d.height + blockH - 1) / blockH
		offsets = d.features[tTileOffsets]
		counts = d.features[tTileBytes]
	} else {
		if rps := d.firstVal(tRowsPerStrip); rps != 0 && int(rps) < d.height {
			blockH = int(rps)
		}
		blocksDown = (d.height + blockH - 1) / blockH
		offsets = d.features[tStripOffsets]
		counts = d.features[tStripBytes]
	}
	if len(offsets) < blocksAcross*blocksDown {
		return nil, tiffFormatError("inconsistent header")
	}
	for i := 0; i < blocksAcross; i++ {
		blkW := blockW
		if !blockPadding && i == blocksAcross-1 && d.width%blockW != 0 {
			blkW = d.width % blockW
		}
		for j := 0; j < blocksDown; j++ {
			blkH := blockH
			if !blockPadding && j == blocksDown-1 && d.height%blockH != 0 {
				blkH = d.height % blockH
			}
			idx := j*blocksAcross + i
			offset := int64(offsets[idx])
			n := int64(0)
			if idx < len(counts) {
				n = int64(counts[idx])
			}
			switch d.firstVal(tCompression) {
			case 0, 1:
				d.buf = make([]byte, n)
				if _, err := d.r.ReadAt(d.buf, offset); err != nil {
					return nil, errTiffNoPixels
				}
			case 5:
				raw := make([]byte, n)
				if _, err := d.r.ReadAt(raw, offset); err != nil {
					return nil, errTiffNoPixels
				}
				d.buf, err = tiffLZWDecode(raw)
				if err != nil {
					return nil, err
				}
			case 8, 32946:
				raw := make([]byte, n)
				if _, err := d.r.ReadAt(raw, offset); err != nil {
					return nil, errTiffNoPixels
				}
				zr, err := zlib.NewReader(bytes.NewReader(raw))
				if err != nil {
					return nil, err
				}
				d.buf, err = io.ReadAll(zr)
				zr.Close()
				if err != nil {
					return nil, err
				}
			case 32773:
				raw := make([]byte, n)
				if _, err := d.r.ReadAt(raw, offset); err != nil {
					return nil, errTiffNoPixels
				}
				d.buf = packBitsDecode(raw)
			default:
				return nil, tiffUnsupportedError("compression")
			}
			d.off = 0
			d.flushBits()
			xmin := i * blockW
			ymin := j * blockH
			if err := d.decodeBlock(img, xmin, ymin, xmin+blkW, ymin+blkH); err != nil {
				return nil, err
			}
		}
	}
	return img, nil
}

func packBitsDecode(src []byte) []byte {
	var dst []byte
	for i := 0; i < len(src); {
		n := int(int8(src[i]))
		i++
		switch {
		case n >= 0:
			end := i + n + 1
			if end > len(src) {
				end = len(src)
			}
			dst = append(dst, src[i:end]...)
			i = end
		case n == -128:
		default:
			if i < len(src) {
				b := src[i]
				i++
				for k := 0; k < 1-n; k++ {
					dst = append(dst, b)
				}
			}
		}
	}
	return dst
}

// tiffLZWDecode implements the MSB-first LZW variant used by TIFF (with the
// "early change" code width switch).
func tiffLZWDecode(src []byte) ([]byte, error) {
	const (
		clearCode = 256
		eoiCode   = 257
	)
	var out []byte
	var bitBuf uint32
	var bitCnt uint
	pos := 0
	width := uint(9)
	prefix := make([]int, 4096)
	suffix := make([]byte, 4096)
	lengths := make([]int, 4096)
	for i := 0; i < 256; i++ {
		prefix[i] = -1
		suffix[i] = byte(i)
		lengths[i] = 1
	}
	next := 258
	prev := -1
	decode := func(code int) []byte {
		l := lengths[code]
		b := make([]byte, l)
		for i := l - 1; i >= 0; i-- {
			b[i] = suffix[code]
			code = prefix[code]
		}
		return b
	}
	for {
		for bitCnt < width {
			if pos >= len(src) {
				return out, nil
			}
			bitBuf = bitBuf<<8 | uint32(src[pos])
			pos++
			bitCnt += 8
		}
		code := int((bitBuf >> (bitCnt - width)) & (1<<width - 1))
		bitCnt -= width
		if code == eoiCode {
			return out, nil
		}
		if code == clearCode {
			next = 258
			width = 9
			prev = -1
			continue
		}
		var entry []byte
		if code < next {
			entry = decode(code)
			if prev >= 0 && next < 4096 {
				prefix[next] = prev
				suffix[next] = entry[0]
				lengths[next] = lengths[prev] + 1
				next++
			}
		} else if code == next && prev >= 0 && next < 4096 {
			first := decode(prev)[0]
			prefix[next] = prev
			suffix[next] = first
			lengths[next] = lengths[prev] + 1
			next++
			entry = decode(code)
		} else {
			return nil, errors.New("tiff: invalid format: bad LZW code")
		}
		out = append(out, entry...)
		prev = code
		if next+1 >= 1<<width && width < 12 {
			width++
		}
	}
}
