func lz77Value(br *vp8lBitReader, prefix int) int {
	if prefix < 4 {
		return prefix + 1
	}
	extraBits := uint((prefix - 2) >> 1)
	offset := (2 + prefix&1) << extraBits
	return offset + int(br.read(extraBits)) + 1
}

type vp8lTransform struct {
	kind     int
	bits     uint
	data     []uint32 // sub image (predictor / colour) or palette
	palSize  int
	origW    int
}

type vp8lDecoder struct {
	br *vp8lBitReader
}

// decodeImageStream decodes an entropy coded image of w x h pixels.
// isMain indicates the ARGB image (which may have a meta Huffman image).
func (d *vp8lDecoder) decodeImageStream(w, h int, isMain bool) ([]uint32, error) {
	br := d.br
	cacheBits := 0
	if br.read(1) == 1 {
		cacheBits = int(br.read(4))
		if cacheBits < 1 || cacheBits > 11 {
			return nil, webpFormatError("bad color cache size")
		}
	}
	var metaBits uint
	var meta []uint32
	numGroups := 1
	if isMain && br.read(1) == 1 {
		metaBits = uint(br.read(3)) + 2
		mw := (w + 1<<metaBits - 1) >> metaBits
		mh := (h + 1<<metaBits - 1) >> metaBits
		var err error
		meta, err = d.decodeImageStream(mw, mh, false)
		if err != nil {
			return nil, err
		}
		for i := range meta {
			g := int(meta[i]>>8) & 0xffff
			meta[i] = uint32(g)
			if g+1 > numGroups {
				numGroups = g + 1
			}
		}
	}
	groups := make([]hgroup, numGroups)
	for i := range groups {
		g, err := readHuffmanGroup(br, cacheBits)
		if err != nil {
			return nil, err
		}
		groups[i] = g
	}
	if br.err != nil {
		return nil, br.err
	}
	pix := make([]uint32, w*h)
	var cache []uint32
	if cacheBits > 0 {
		cache = make([]uint32, 1<<cacheBits)
	}
	insert := func(c uint32) {
		if cache != nil {
			cache[(c*0x1e35a7bd)>>(32-uint(cacheBits))] = c
		}
	}
	for i := 0; i < len(pix); {
		if br.err != nil {
			return nil, br.err
		}
		x, y := i%w, i/w
		g := &groups[0]
		if meta != nil {
			mw := (w + 1<<metaBits - 1) >> metaBits
			g = &groups[meta[(y>>metaBits)*mw+(x>>metaBits)]]
		}
		s := g[0].decode(br)
		switch {
		case s < numLiteralCodes:
			red := uint32(g[1].decode(br))
			blue := uint32(g[2].decode(br))
			alpha := uint32(g[3].decode(br))
			c := alpha<<24 | red<<16 | uint32(s)<<8 | blue
			pix[i] = c
			insert(c)
			i++
		case s < numLiteralCodes+numLengthCodes:
			length := lz77Value(br, s-numLiteralCodes)
			distSym := g[4].decode(br)
			distCode := lz77Value(br, distSym)
			var dist int
			if distCode > 120 {
				dist = distCode - 120
			} else {
				dx, dy := int(distanceMap[distCode-1][0]), int(distanceMap[distCode-1][1])
				dist = dx + dy*w
				if dist < 1 {
					dist = 1
				}
			}
			if dist > i || i+length > len(pix) {
				return nil, webpFormatError("bad LZ77 reference")
			}
			for k := 0; k < length; k++ {
				pix[i] = pix[i-dist]
				insert(pix[i])
				i++
			}
		default:
			idx := s - numLiteralCodes - numLengthCodes
			if cache == nil || idx >= len(cache) {
				return nil, webpFormatError("bad color cache index")
			}
			pix[i] = cache[idx]
			i++
		}
	}
	return pix, nil
}

func vp8lDecode(data []byte) (image.Image, error) {
	w, h, _, err := vp8lHeader(data)
	if err != nil {
		return nil, err
	}
	d := &vp8lDecoder{br: &vp8lBitReader{data: data[1:]}}
	d.br.read(14 + 14 + 1 + 3)
	br := d.br

	var transforms []vp8lTransform
	seen := [4]bool{}
	xsize := w
	for br.read(1) == 1 {
		kind := int(br.read(2))
		if seen[kind] {
			return nil, webpFormatError("repeated transform")
		}
		seen[kind] = true
		t := vp8lTransform{kind: kind, origW: xsize}
		switch kind {
		case 0, 1: // predictor, colour transform
			t.bits = uint(br.read(3)) + 2
			bw := (xsize + 1<<t.bits - 1) >> t.bits
			bh := (h + 1<<t.bits - 1) >> t.bits
			t.data, err = d.decodeImageStream(bw, bh, false)
			if err != nil {
				return nil, err
			}
		case 2: // subtract green
		case 3: // colour indexing
			t.palSize = int(br.read(8)) + 1
			t.data, err = d.decodeImageStream(t.palSize, 1, false)
			if err != nil {
				return nil, err
			}
			for i := 1; i < t.palSize; i++ {
				t.data[i] = addPixels(t.data[i], t.data[i-1])
			}
			switch {
			case t.palSize <= 2:
				t.bits = 3
			case t.palSize <= 4:
				t.bits = 2
			case t.palSize <= 16:
				t.bits = 1
			default:
				t.bits = 0
			}
			xsize = (xsize + 1<<t.bits - 1) >> t.bits
		}
		transforms = append(transforms, t)
	}
	pix, err := d.decodeImageStream(xsize, h, true)
	if err != nil {
		return nil, err
	}
	// apply inverse transforms in reverse order
	for i := len(transforms) - 1; i >= 0; i-- {
		t := transforms[i]
		switch t.kind {
		case 0:
			applyPredictor(pix, t.origW, h, t)
		case 1:
			applyColorTransform(pix, t.origW, h, t)
		case 2:
			for j, p := range pix {
				g := (p >> 8) & 0xff
				r := ((p >> 16 & 0xff) + g) & 0xff
				b := ((p & 0xff) + g) & 0xff
				pix[j] = p&0xff00ff00 | r<<16 | b
			}
		case 3:
			pix = applyColorIndexing(pix, t.origW, h, t)
		}
	}
	img := image.NewNRGBA(image.Rect(0, 0, w, h))
	for i, p := range pix {
		img.Pix[i*4+0] = uint8(p >> 16)
		img.Pix[i*4+1] = uint8(p >> 8)
		img.Pix[i*4+2] = uint8(p)
		img.Pix[i*4+3] = uint8(p >> 24)
	}
	return img, nil
}

func addPixels(a, b uint32) uint32 {
	alpha := (a>>24 + b>>24) & 0xff
	red := ((a>>16)&0xff + (b>>16)&0xff) & 0xff
	green := ((a>>8)&0xff + (b>>8)&0xff) & 0xff
	blue := (a&0xff + b&0xff) & 0xff
	return alpha<<24 | red<<16 | green<<8 | blue
}

func avg2(a, b uint32) uint32 {
	return (((a ^ b) & 0xfefefefe) >> 1) + (a & b)
}

func abs32(x int32) int32 {
	if x < 0 {
		return -x
	}
	return x
}

func selectPred(l, t, tl uint32) uint32 {
	pa := abs32(int32(t>>24)-int32(tl>>24)) + abs32(int32(t>>16&0xff)-int32(tl>>16&0xff)) + abs32(int32(t>>8&0xff)-int32(tl>>8&0xff)) + abs32(int32(t&0xff)-int32(tl&0xff))
	pl := abs32(int32(l>>24)-int32(tl>>24)) + abs32(int32(l>>16&0xff)-int32(tl>>16&0xff)) + abs32(int32(l>>8&0xff)-int32(tl>>8&0xff)) + abs32(int32(l&0xff)-int32(tl&0xff))
	// pa is the "distance" if we pick L (predict T - TL + L vs T), per spec
	if pa < pl {
		return l
	}
	return t
}

func clamp255(v int32) uint32 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint32(v)
}

func clampAddSubtractFull(a, b, c uint32) uint32 {
	var out uint32
	for s := uint(0); s < 32; s += 8 {
		v := int32(a>>s&0xff) + int32(b>>s&0xff) - int32(c>>s&0xff)
		out |= clamp255(v) << s
	}
	return out
}

func clampAddSubtractHalf(a, b uint32) uint32 {
	var out uint32
	for s := uint(0); s < 32; s += 8 {
		av := int32(a >> s & 0xff)
		bv := int32(b >> s & 0xff)
		v := av + (av-bv)/2
		out |= clamp255(v) << s
	}
	return out
}

func applyPredictor(pix []uint32, w, h int, t vp8lTransform) {
	bw := (w + 1<<t.bits - 1) >> t.bits
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			i := y*w + x
			var pred uint32
			switch {
			case x == 0 && y == 0:
				pred = 0xff000000
			case y == 0:
				pred = pix[i-1]
			case x == 0:
				pred = pix[i-w]
			default:
				mode := (t.data[(y>>t.bits)*bw+(x>>t.bits)] >> 8) & 0xf
				l, tp, tl := pix[i-1], pix[i-w], pix[i-w-1]
				var tr uint32
				if x == w-1 {
					tr = pix[i-w+1-w+w] // leftmost pixel of current row: index y*w
					tr = pix[y*w]
				} else {
					tr = pix[i-w+1]
				}
				switch mode {
				case 0:
					pred = 0xff000000
				case 1:
					pred = l
				case 2:
					pred = tp
				case 3:
					pred = tr
				case 4:
					pred = tl
				case 5:
					pred = avg2(avg2(l, tr), tp)
				case 6:
					pred = avg2(l, tl)
				case 7:
					pred = avg2(l, tp)
				case 8:
					pred = avg2(tl, tp)
				case 9:
					pred = avg2(tp, tr)
				case 10:
					pred = avg2(avg2(l, tl), avg2(tp, tr))
				case 11:
					pred = selectPred(l, tp, tl)
				case 12:
					pred = clampAddSubtractFull(l, tp, tl)
				case 13:
					pred = clampAddSubtractHalf(avg2(l, tp), tl)
				default:
					pred = 0xff000000
				}
			}
			pix[i] = addPixels(pix[i], pred)
		}
	}
}

func colorDelta(t int8, c int8) int32 {
	return (int32(t) * int32(c)) >> 5
}

func applyColorTransform(pix []uint32, w, h int, t vp8lTransform) {
	bw := (w + 1<<t.bits - 1) >> t.bits
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			i := y*w + x
			m := t.data[(y>>t.bits)*bw+(x>>t.bits)]
			g2r := int8(m >> 0)
			g2b := int8(m >> 8)
			r2b := int8(m >> 16)
			p := pix[i]
			g := int8(p >> 8)
			r := int32(p>>16&0xff) + colorDelta(g2r, g)
			r &= 0xff
			b := int32(p&0xff) + colorDelta(g2b, g) + colorDelta(r2b, int8(r))
			b &= 0xff
			pix[i] = p&0xff00ff00 | uint32(r)<<16 | uint32(b)
		}
	}
}

func applyColorIndexing(pix []uint32, w, h int, t vp8lTransform) []uint32 {
	out := make([]uint32, w*h)
	xsize := (w + 1<<t.bits - 1) >> t.bits
	perPixel := 8 >> t.bits
	mask := uint32(1)<<perPixel - 1
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			packed := pix[y*xsize+(x>>t.bits)]
			shift := uint(x&(1<<t.bits-1)) * uint(perPixel)
			idx := int((packed >> 8 >> shift) & mask)
			if idx < t.palSize {
				out[y*w+x] = t.data[idx]
			}
		}
	}
	return out
}

